window.NIGHTS.cases[3]={"nr":3,"id":"case03","title":"Scherben","subtitle":"","level":"Persönliche Ebene","from":61,"to":83,"mythen":[],"sections":[{"id":"titel-und-pitch","kind":"intro","title":"Titel und Pitch","page":61,"layer":null,"blocks":5},{"id":"dr-krystal-knight","kind":"place","title":"DR. KRYSTAL KNIGHT","page":62,"layer":null,"blocks":18},{"id":"heilung-fuer-die-gebrochenen","kind":"place","title":"HEILUNG FÜR DIE GEBROCHENEN","page":63,"layer":null,"blocks":5},{"id":"es-kommt-ein-schneesturm","kind":"place","title":"ES KOMMT EIN SCHNEESTURM","page":63,"layer":null,"blocks":3},{"id":"schicht-0-aufhaenger","kind":"layer","title":"SCHICHT 0: AUFHÄNGER","page":64,"layer":null,"blocks":6},{"id":"schicht-1-schrei-nach-hilfe","kind":"layer","title":"SCHICHT 1: SCHREI NACH HILFE","page":65,"layer":null,"blocks":1},{"id":"wohnung-der-familie-jones","kind":"place","title":"WOHNUNG DER FAMILIE JONES","page":65,"layer":"schicht-1-schrei-nach-hilfe","blocks":12},{"id":"privatklinik-von-heilung-fuer-die-gebrochenen","kind":"place","title":"PRIVATKLINIK VON HEILUNG FÜR DIE GEBROCHENEN","page":66,"layer":"schicht-1-schrei-nach-hilfe","blocks":39},{"id":"supervision","kind":"place","title":"SUPERVISION","page":69,"layer":"schicht-1-schrei-nach-hilfe","blocks":9},{"id":"der-misslungene-golem","kind":"place","title":"DER MISSLUNGENE GOLEM","page":70,"layer":"schicht-1-schrei-nach-hilfe","blocks":46},{"id":"schicht-2-ein-kuehler-empfang","kind":"layer","title":"SCHICHT 2: EIN KÜHLER EMPFANG","page":73,"layer":null,"blocks":1},{"id":"die-anstalt","kind":"place","title":"DIE ANSTALT","page":73,"layer":"schicht-2-ein-kuehler-empfang","blocks":33},{"id":"die-historische-gesellschaft","kind":"place","title":"DIE HISTORISCHE GESELLSCHAFT","page":76,"layer":"schicht-2-ein-kuehler-empfang","blocks":25},{"id":"schicht-3-steine-im-glashaus","kind":"layer","title":"SCHICHT 3: STEINE IM GLASHAUS","page":79,"layer":null,"blocks":1},{"id":"aurora-glas","kind":"place","title":"AURORA GLAS","page":79,"layer":"schicht-3-steine-im-glashaus","blocks":8},{"id":"die-spezialabteilung","kind":"place","title":"DIE „SPEZIALABTEILUNG“","page":79,"layer":"schicht-3-steine-im-glashaus","blocks":28},{"id":"schicht-4-herzschneeschippen","kind":"layer","title":"SCHICHT 4: HERZSCHNEESCHIPPEN","page":82,"layer":null,"blocks":1},{"id":"ein-schneesturm-des-hasses","kind":"place","title":"EIN SCHNEESTURM DES HASSES","page":82,"layer":"schicht-4-herzschneeschippen","blocks":24}],"pages":{"61":{"tab":"","blocks":[{"t":"sh","x":"<b>EIN ERSCHRECKENDER FALL UM ZERRÜTTETE SEELEN</b>","sz":20.0,"box":[123.5,784.6,489.5,804.6],"p":61,"i":0,"sec":"titel-und-pitch"}],"size":[595.276,841.89]},"62":{"tab":"","blocks":[{"t":"p","x":"In letzter Zeit weht ein untergründiger Hass durch die Straßen, bitterkalt und blutrünstig. Die Menschen wissen nicht einmal, was sie hassen. Sie hassen: einander, ihr Leben und sich selbst. Könnte Heilung für die Gebrochenen, ein Unterstützungsnetzwerk für die, die über den Nebel hinausblicken, die Rettungsleine sein, die die Stadt braucht? Während das Team diese Welle dunkler Emotionen einzudämmen versucht, könnten derselbe eiskalte Hass auch in ihren Herzen Wurzeln schlagen.","sz":13.0,"box":[53.9,60.1,285.2,247.1],"p":62,"i":0,"sec":"titel-und-pitch"},{"t":"p","x":"<i>Scherben</i> ist ein psychologischer Thriller, in dem das Team gegen eine Superschurkin antritt, die intensive Emotionen hervorrufen kann. Eine gute Gelegenheit, die emotionalen Nöte der Protagonist:innen zu erkunden. Die Ermittlungen führen das Team zu einer pervertierten Organisation für geistige Gesundheit. Mehrere optionale Nebenschauplätze, die du nach Belieben für mehr Dramatik und Action einfügen kannst, lockern den Fall auf. Der Fall gipfelt in einer Auseinandersetzung unter Zeitdruck mit der Schurkin, die einen ultimativen Plan hat.","sz":9.5,"box":[53.9,257.6,285.8,392.1],"p":62,"i":1,"sec":"titel-und-pitch"},{"t":"p","x":"<b>Je nachdem, wie du den Fall anlegen willst, solltest du mit deiner Gruppe besprechen, wie ihr mit intensiven SC-Emotionen und Themen wie psychische Gesundheit umgehen wollt (s. S. Psychische Zustände und Krankheiten im Spiel, S. 21).</b>","sz":9.5,"box":[53.9,400.9,283.5,460.4],"p":62,"i":2,"sec":"titel-und-pitch"},{"t":"p","x":"Als Finale der persönlichen Ebene enthält dieser Fall Begegnungen mit mächtigen Gegner:innen, die für ein gut vorbereitetes Team von Veteranen geeignet sind (z. B. ein optionales Zusammentreffen mit einem Team von Elite-Sturmtruppen der Torwächter, die Risse möglicherweise in Schläfer zurückverwandeln können). Passe den Schwierigkeitsgrad an dein Team an.","sz":9.5,"box":[53.9,469.0,285.8,553.5],"p":62,"i":3,"sec":"titel-und-pitch"},{"t":"h","x":"DR. KRYSTAL KNIGHT","sz":16.0,"box":[53.9,605.5,196.0,621.5],"p":62,"i":4,"skip":true,"sec":"dr-krystal-knight"},{"t":"sh","x":"<b>GUTE ABSICHTEN</b>","sz":10.0,"box":[54.3,630.3,151.0,640.3],"p":62,"i":5,"sec":"dr-krystal-knight"},{"t":"p","x":"In den Anfangsjahren der Stadt war Krystal Knight (Die Schneekönigin) eine aussichtsreiche Psychotherapeutin, die danach strebte, die Gesellschaft von ihren emotionalen Wunden zu heilen. Knight stammte aus einer Adelsfamilie und nutzte ihr Familienvermögen für Zugang zu den exklusiven Psychologen-Vereinen der Stadt. Einige deren Mitglieder hatten bei den Gründervätern und -müttern der Stadt studiert. Unter deren Anleitung ließ sie sich zur Psychiaterin ausbilden und spezialisierte sich auf kriminelles Verhalten,","sz":9.5,"box":[53.9,645.9,285.7,767.9],"p":62,"i":6,"sec":"dr-krystal-knight"},{"t":"p","x":"um dann zwei Jahrzehnte damit zuzubringen, ihre therapeutischen Fähigkeiten zu perfektionieren.","sz":9.5,"box":[309.0,59.9,520.0,81.9],"p":62,"i":7,"sec":"dr-krystal-knight"},{"t":"p","x":"Fasziniert von der Macht der Worte, die die Wunden der Vergangenheit heilen können, aber desillusioniert von der Korruption des Systems, konzentrierte sie sich darauf, den Wirtschaftskriminellen der Stadt – korrupten Politiker:innen und Geschäftsleuten – eine Therapie anzubieten und ihnen zu helfen, bessere Menschen zu werden. Sie hatte Hoffnung, damit die gesamte Stadt zu heilen. Ihre Therapien waren bei den Reichen und Mächtigen der Stadt sehr gefragt, aber es kam zu keinem gesellschaftlichen Wandel. Eine verborgene Kraft schien die Menschen in der Stadt auf dem Weg der Entfremdung, Vereinsamung und Gewalt zu halten.","sz":9.5,"box":[309.0,90.6,540.7,237.6],"p":62,"i":8,"sec":"dr-krystal-knight"},{"t":"sh","x":"<b>DER WEG ZUR HÖLLE</b>","sz":10.0,"box":[309.4,251.2,425.1,261.2],"p":62,"i":9,"sec":"dr-krystal-knight"},{"t":"p","x":"Dr. Knight übte ihren Beruf weiter aus und übersah dabei ihre wachsende Verbitterung über ihr Leben und die unerfüllte Vision. Als sie hörte, dass Corbin Payne, „der Mann, der die Stadt war“, krank und depressiv war, bot sie ihm ihre Dienste an um, dem einflussreichsten Menschen der Stadt zu helfen. Da er noch kein Avatar war, glaubte Payne noch an eine mögliche Heilung und willigte ein.","sz":9.5,"box":[309.0,266.8,537.7,363.8],"p":62,"i":10,"sec":"dr-krystal-knight"},{"t":"p","x":"Die beiden verbrachten Jahre mit intensiven täglichen Analyse-Sitzungen. Wie radioaktiver Müll sickerte das legendäre Elend Paynes in die Seele der Ärztin und infizierte sie, untergrub ihre natürliche Zuversicht und mentale Stärke. In den Sitzungen war sie die optimistische Heilerin, aber außerhalb lag ihr Leben in Trümmern, und sie begann, alles und jeden zu hassen.","sz":9.5,"box":[309.0,372.4,541.0,456.9],"p":62,"i":11,"sec":"dr-krystal-knight"},{"t":"p","x":"Schließlich brach sie der König. Um ihre Verwandlung in eine Gralsritterin zu vollenden, schenkte er ihr ein Relikt, den Teufelsspiegel (aus Andersens <i>Die Schneekönigin</i>), der sie sofort als Trägerin annahm und sie als Schneekönigin erwachen ließ. Betrachtete sie sich im Spiegel, sah sie täglich die schlechtesten Eigenschaften in ihrem Leben, das, was am Abscheulichsten und Verwerflichsten war. Da Payne die Macht des Spiegels kannte, überließ er ihr (die das zuerst nicht interessierte) eine der letzten Firmen seines zerfallenden Bauimperiums, <b>Aurora Glas</b>, die Fenster, Windschutzscheiben und Schaufenster für die ganze Stadt herstellte. Dann ging er und ließ sie mit ihrem Versagen, dem Selbsthass und hasserfüllten Herzen zurück.","sz":9.5,"box":[309.0,465.6,539.3,637.6],"p":62,"i":12,"sec":"dr-krystal-knight"},{"t":"sh","x":"<b>IN DER ANSTALT</b>","sz":10.0,"box":[309.4,651.2,400.2,661.2],"p":62,"i":13,"sec":"dr-krystal-knight"},{"t":"p","x":"Der Teufelsspiegel, der in ihrem Badezimmer hing, brachte Krystal Knight immer mehr um den Verstand, bis er ihren Geist in Scherben brach, als sie ihn zerschmetterte. Winzige Splitter des Spiegels bohrten sich in ihre Augen und ihr Herz. Den Rest ließ sie in","sz":9.5,"box":[309.0,666.8,534.7,726.3],"p":62,"i":14,"sec":"dr-krystal-knight"}],"size":[595.276,841.89]},"63":{"tab":"","blocks":[{"t":"h","x":"WARUM SCHLUG DIE THERAPIE FEHL?","sz":14.0,"box":[65.2,69.5,241.3,83.5],"p":63,"i":0,"sec":"dr-krystal-knight"},{"t":"p","x":"Sowohl Knight als auch Payne hatten viel Zeit, über die Vergangenheit nachzudenken und sie zu verarbeiten. Obwohl sie es nicht zugibt, weiß die Ärztin, dass ihr Versagen Ergebnis der kindischen Besessenheit war, andere zu heilen, während sie die Dunkelheit in ihrem Inneren ignorierte. Dieses Versagen hat sich in ihren Geist eingebrannt und ihren Selbsthass genährt. Sie hasst sich selbst dafür, dass sie die Chance, Gutes zu tun, verpasst hat.","sz":9.0,"box":[65.2,96.0,274.7,201.0],"p":63,"i":1,"sec":"dr-krystal-knight"},{"t":"p","x":"Payne hat eine leicht andere Meinung zu diesem Thema. Für ihn war es töricht, dass eine Schläferin versucht hat, sich mit Kräften zu messen, die sie nicht begreifen konnte - wie mit dem Mythos des Fischerkönigs. Manchmal denkt er, dass er ihr den Spiegel nur deshalb gegeben haben, damit sie als Riss erwacht, ihre Probleme aufarbeitet und mit einer echten Chance zurückkommt, ihn zu heilen.","sz":9.0,"box":[65.2,209.7,266.0,302.7],"p":63,"i":2,"sec":"dr-krystal-knight"},{"t":"p","x":"ihrer Glasfabrik einschmelzen. Die Ärztin bekam einen selbstzerstörerischen Wutausbruch, man erklärte sie für geistig instabil (in der damaligen Sprache) und schickte sie in die <b>Städtische Anstalt für kriminelle Geisteskranke</b>, unter der Leitung ihrer Rivalin <b>Esther Monahan</b>.","sz":9.5,"box":[53.9,339.8,284.4,412.0],"p":63,"i":3,"sec":"dr-krystal-knight"},{"t":"p","x":"Diese unterzog Knight vielen kruden, ineffektiven Therapien, darunter ungetestete Medikamente, Schocktherapie und eine Lobotomie. Sie hätte das gesamte medizinische Personal einfrieren können, hielt sich aber zurück und nutzte die Behandlung als mythische Form der Selbstverstümmelung, als Ventil für den Hass, den sie gegen sich selbst empfand. Unheilbar gebrochen verbrachte sie die nächsten Jahrzehnte in den Tiefen der Anstalt in Einzelhaft. Ihr eisiger Mythos konservierte ihren Körper, sie alterte nicht.","sz":9.5,"box":[53.9,420.5,286.2,542.5],"p":63,"i":4,"sec":"dr-krystal-knight"},{"t":"sh","x":"<b>WECHSEL DER POLARITÄT</b>","sz":10.0,"box":[54.3,556.1,199.0,566.1],"p":63,"i":5,"sec":"dr-krystal-knight"},{"t":"p","x":"Dank des Nebels vergaß sogar die Anstalt Krystal Knight. Als die Foltertherapie aufhörte, fehlte ihr die Selbstverletzung als Ventil für ihren legendären Hass, und so wandten sich ihre Gedanken und Wut nach außen. Krystal Knight plante ihre Rache an der Stadt, die ihr Peiniger Corbin Payne erbaut hatte. Sie würde sie in einem Schneesturm des Hasses zerstören, beginnend mit den Rissen, denn sie waren der Person am ähnlichsten, die sie am meisten hasste: sich selbst.","sz":9.5,"box":[53.9,571.7,284.0,681.2],"p":63,"i":6,"sec":"dr-krystal-knight"},{"t":"h","x":"HEILUNG FÜR DIE GEBROCHENEN","sz":16.0,"box":[53.9,696.9,270.0,712.9],"p":63,"i":7,"skip":true,"sec":"heilung-fuer-die-gebrochenen"},{"t":"p","x":"Es war leicht für einen von Hass erfüllten Riss von Knights Macht, die Anstalt zu übernehmen. Sie fror ihre Zellentür ein, tötete einige Angehörige des Wachpersonals und Pflegekräfte und quälte die inzwischen","sz":9.5,"box":[53.9,716.8,283.4,763.8],"p":63,"i":8,"sec":"heilung-fuer-die-gebrochenen"},{"t":"p","x":"betagte Esther Monahan tagelang, bevor sie sich ihrer entledigte. Dann zwang sie alle, sie als Esther Monahan zu akzeptieren oder zu sterben, und übernahm den Platz als Chefin der Einrichtung.","sz":9.5,"box":[309.0,59.9,535.4,106.9],"p":63,"i":9,"sec":"heilung-fuer-die-gebrochenen"},{"t":"p","x":"Als Nächstes wandte sie sich an die Mitarbeiter:innen. Indem sie sie in Gummizellen sperrte und zwang, an „Therapiesitzungen“ mit ihr teilzunehmen, überzeugte Dr. Knight das Team von Psychiater:innen und Psycholog:innen, dass ein Riss eine Perversion war. Sie konnten die Existenz als Riss nicht „heilen“ oder die Betroffenen „bekehren“ und mussten sich eine andere „Heilung“ einfallen lassen. So entstand eine Therapie, bei der Patient:in die katastrophalen Folgen des Riss-Seins vor Augen geführt wurden. Sie sollten dann entscheiden, was sie tun. Aufgrund von Dr. Knights Kräften führte dies meist dazu, dass die Risse starke Hassgefühle entwickelten und schließlich versuchten, sich selbst oder Ihresgleichen zu verletzen.","sz":9.5,"box":[309.0,115.6,540.5,287.6],"p":63,"i":10,"sec":"heilung-fuer-die-gebrochenen"},{"t":"p","x":"Dr. Knight und ihr Team wandten sich an die psychosozialen Kreise der Stadt und veröffentlichten Studien, die Leser:innen aufrüttelten. Die von ihr und ihren Schüler:innen ausgebildeten Therapeut:innen gründeten <b>Heilung für die Gebrochenen</b>, eine Organisation von erwachten Therapeut:innen, die Rissen „helfen“ wollten – indem sie sie dazu brachten, sich selbst oder andere wie sie zu verletzen. Heilung für die Gebrochenen bekam einen Ruf unter Rissen – als ein Unterstützungsprogramm mit kostenlosen Therapiesitzungen und Werbung, an das man sich in Krisenzeiten wenden konnte. Die Therapeut:innen vermieden es, mit dem schrecklichen Ergebnis ihrer „Therapie“ in Verbindung gebracht zu werden, indem sie die Schuld subtil den Opfern und den Umständen zuschoben.","sz":9.5,"box":[309.0,296.3,540.3,480.8],"p":63,"i":11,"sec":"heilung-fuer-die-gebrochenen"},{"t":"h","x":"ES KOMMT EIN SCHNEESTURM","sz":16.0,"box":[309.0,496.4,515.6,512.4],"p":63,"i":12,"skip":true,"sec":"es-kommt-ein-schneesturm"},{"t":"p","x":"Die Bemühungen von Heilung für die Gebrochenen waren nur zum Teil erfolgreich, oft vereitelt durch andere Risse (zuletzt möglicherweise das Team in <i>Der sanfte Tod</i> und <i>Kirmes der Maschinen</i>). Zu Krystal Knights Glück braucht es nur noch wenig Hass, um den letzten Angriff auf die Stadt durchzuführen.","sz":9.5,"box":[309.0,516.4,540.7,588.4],"p":63,"i":13,"sec":"es-kommt-ein-schneesturm"},{"t":"p","x":"Aurora Glas war weiterhin bei Bauvorhaben der wichtigste Glaslieferant der Stadt, trotz einer Besitzerin in der Anstalt. Fast jede Scheibe enthält einen Bruchteil der Kraft des Spiegels, dessen Scherben in den Fabriken der Firma eingeschmolzen wurden, und Krystal spürt das. Mit genug Hass würden <b>alle Fenster der Stadt auf einmal brechen</b>, und die magischen, eisigen Scherben würden den Hass überall verbreiten und einen Aufruhr auslösen. Heilung für die Gebrochenen hat bald genug emotionale Ladung, dass Krystal den lieblosen Winter, nach dem sie sich so sehnt, auf die Stadt loslässt","sz":9.5,"box":[309.0,597.0,536.6,744.0],"p":63,"i":14,"sec":"es-kommt-ein-schneesturm"}],"size":[595.276,841.89]},"64":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 0:","sz":14.0,"box":[53.9,485.8,122.3,499.8],"p":64,"i":0,"skip":true,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"AUFHÄNGER","sz":23.0,"box":[53.9,508.1,170.2,531.1],"p":64,"i":1,"skip":true},{"t":"p","x":"Folgendermaßen kannst du das Team in den Fall einbeziehen:","sz":9.5,"box":[53.9,542.4,278.0,564.4],"p":64,"i":2,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Das Team hat aus den früheren Fällen,</b> <i>Der sanfte Tod</i> und <i>Kirmes der Maschinen,</i> Hinweise, da beide Schurk:innen Risse und mit Therapeut:innen von Heilung für die Gebrochenen in Kontakt sind. Unabhängig davon, ob das Team ihnen glaubt, dass die Therapeut:innen sie dazu getrieben haben, sollten die SC dieser Spur nachgehen und Martha Ellis‘ Therapeutin, <b>Dr. Selma Perrin</b>, oder Maximilian Drakes Therapeuten, <b>Dr. Archibald Tennant</b>, ausfindig machen. Beide betreiben <b>Privatkliniken</b>, die leicht zu finden sind. Das Team könnte auch Heilung für die Gebrochenen im Allgemeinen untersuchen (s. S. <u>Die Privatklinik von Heilung für die Gebrochen).</u>","sz":9.5,"box":[53.9,575.9,284.0,735.4],"p":64,"i":3,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• <b>Ausgepowerte Protagonist:innen oder Nebenfiguren könnten Hilfe bei Heilung für die Gebrochenen suchen.</b> Eine klassische Eröffnungsszene zeigt eine oder mehrere Protagonist:innen in einer <b>Selbsthilfegruppe für Risse</b>, wo sie über ihre Probleme sprechen oder anderen zuhören. <b>Harry Yang</b>, ein Schläfer, der in den Bann von Dr. Knights neuen Theorien gerät, aber noch wirklich helfen will, leitet die Selbsthilfegruppe in einem örtlichen Gemeindezentrum oder im Keller eines Privathauses. Harry kann Rissen mit Problemen eine Therapie empfehlen, was zu einem Treffen in einer der Privatkliniken führt. Nebenfiguren, die jemanden von Heilung für die Gebrochenen aufsuchen, wirken danach verstört, was Besorgnis wecken könnte.","sz":9.5,"box":[309.0,541.8,539.2,726.3],"p":64,"i":4,"sec":"schicht-0-aufhaenger"}],"size":[595.276,841.89]},"65":{"tab":"","blocks":[{"t":"p","x":"• <b>Officer Das</b> (s. S. <i>Der sanfte Tod</i>) könnte, wenn sie regelmäßig Teil der Serie ist, diejenige sein, die Hilfe durch Therapie sucht. Ihre besonderen Kräfte könnten etwas Schutz vor der Gehirnwäsche bieten, so dass sie auch als Informantin dienen könnte, die das Team darüber informiert, was die Therapeut:innenorganisation wirklich vorhat.","sz":9.5,"box":[53.9,62.5,281.0,147.0],"p":65,"i":0,"sec":"schicht-0-aufhaenger"},{"t":"p","x":"• Wenn du diesen Fall als One-Shot spielen oder Szenen hinzufügen möchtest, kann das Team zu einem Fall von <b>häuslicher Gewalt</b> gerufen werden, der sie zu Heilung für die Gebrochenen führt. <b>Felicia Pema Jones</b> (<i>Palden Lhamo</i>, die zornigen Schutzgöttin Tibets und seiner geistigen Führer) ist eine junge Mutter, die nach der Geburt depressiv und gewalttätig ist. Ihr Ehemann Jeff hat den Sozialdienst oder die Polizei gerufen, um Hilfe zu bekommen, oder das Team erreicht, weil er sie für besessen hält. Diese Spur beginnt in der <u>Wohnung der Familie Jones.</u>","sz":9.5,"box":[53.9,155.7,284.0,290.2],"p":65,"i":1,"sec":"schicht-0-aufhaenger"},{"t":"h","x":"SCHICHT 1:","sz":14.0,"box":[53.9,306.7,120.8,320.7],"p":65,"i":2,"skip":true,"sec":"schicht-1-schrei-nach-hilfe"},{"t":"h","x":"SCHREI NACH HILFE","sz":23.0,"box":[53.9,329.1,243.9,352.1],"p":65,"i":3,"skip":true},{"t":"h","x":"WOHNUNG DER FAMILIE JONES","sz":16.0,"box":[79.7,365.7,285.0,381.7],"p":65,"i":4,"skip":true,"sec":"wohnung-der-familie-jones"},{"t":"ro","x":"Ihr könnt euer Pech kaum fassen, als euch vor dem Mietshaus, in dem die Familie Jones wohnt, sintflutartigen Regenschauer erwarten. Klatschnass betretet ihr die enge Wohnung. Jeff Jones empfängt und führt euch zum Kinderzimmer, während er von den Wutausbrüchen erzählt, die seine Frau Felicia seit der Geburt ihres ersten Kindes, Mira, hat. Er klopft, aber es kommt keine Antwort. Durch das Schlüsselloch sieht man ein düsteres Kinderzimmer, zugig mit offenem Fenster samt zerrissenen Vorhängen. In der Ecke singt jemand leise ein Kinderlied.","sz":9.0,"box":[62.4,384.0,283.8,533.4],"p":65,"i":5,"sec":"wohnung-der-familie-jones"},{"t":"p","x":"Felicia Pema Jones ist eines der zahlreichen Opfer von Heilung für die Gebrochenen. Die Mutter der drei Monate alten Mira erwachte nach der Geburt als Riss Palden Lhamos, der tibetischen Schutzgöttin, möglicherweise wegen des tiefen Wunsches, Mira zu beschützen und für sie alles Gute der Welt zu bewahren. Leider kann Palden Lhamo eine zornige Göttin sein, die Gefahren für ihre Schützlinge gewaltsam aus dem Weg schafft. Felicia wusste nicht, wie sie mit dieser brennenden Wut umgehen sollte.","sz":9.5,"box":[53.9,542.4,280.1,664.4],"p":65,"i":6,"sec":"wohnung-der-familie-jones"},{"t":"p","x":"In ihrer Not wandte sie sich an Heilung für die Gebrochenen, wo man sie an den jungianischen Therapeuten <b>Dr. Drew Langstone</b> verwies.","sz":9.5,"box":[53.9,673.1,285.6,707.7],"p":65,"i":7,"sec":"wohnung-der-familie-jones"},{"t":"p","x":"Natürlich wurden die Dinge schlimmer. Langstone flößte Felicia zerstörerische Ideen ein, indem er den Kindermord in ihrer Mythos-Geschichte nutzte. Er will Felicia dazu bringen, ihre Tochter zu töten und Selbstmord zu begehen (zum Wohle aller, so glaubt er).","sz":9.5,"box":[309.0,59.9,539.2,119.4],"p":65,"i":8,"sec":"wohnung-der-familie-jones"},{"t":"p","x":"Als das Team eintrifft, ist Felicia kurz davor genau das zu tun – sie hat sich mit Mira im Kinderzimmer eingeschlossen und schreit Jeff immer wieder an sich fernzuhalten. Das Team kann den von Langstone angerichteten Schaden rückgängig machen und Felicias Hilfe bei der Suche nach der Wahrheit bekommen - aber zuerst müssen die SC Mutter und Kind retten.","sz":9.5,"box":[309.0,128.1,533.0,212.6],"p":65,"i":9,"sec":"wohnung-der-familie-jones"},{"t":"p","x":"Wenn Felicia das Undenkbare tut, dann indem sie sich und/oder Mira durch das Kinderzimmerfenster wirft und mit dem <b>Motiv der Scherben</b> in den glasübersäten Tod stürzt (s. S. 22).","sz":9.5,"box":[309.0,221.3,536.4,268.3],"p":65,"i":10,"sec":"wohnung-der-familie-jones"},{"t":"card","x":"<b>Jeff informiert über Felicias psychische Verfassung.</b> Es ging ihr bis Miras Geburt gut. Als Felicias Wutausbrüche begannen, suchte das Paar Hilfe, aber Felicia hatte nicht das Gefühl, dass der (Schläfer-)Therapeut ihr helfen konnte. Später sah sie ein Plakat von Heilung für die Gebrochenen, rief bei der Beratungsstelle an, und man verwies sie an Dr. Drew Langstone, der noch immer ihr Therapeut ist.","sz":null,"k":"yellow","box":[309.3,282.2,541.7,403.8],"p":65,"i":11,"sec":"wohnung-der-familie-jones"},{"t":"card","x":"Jeff ist frustriert, weil er Felicia nicht helfen kann und macht sich große Sorgen um ihre und Miras Sicherheit. Er erklärt Felicias Zustand und außerordentliche Stärke als Nebenwirkungen der Wut.","sz":null,"k":"yellow","box":[309.3,412.7,541.7,484.1],"p":65,"i":12,"sec":"wohnung-der-familie-jones"},{"t":"card","x":"<b>Felicia murmelt in ihrer Wut vielleicht etwas, das ihren inneren Konflikt verrät</b>: Sie ist besorgt, dass ihre Tochter auch ein Riss sein könnte, was eine „schmutzige, hässliche Sache“ ist, und erwägt, sowohl sich selbst als auch ihre Tochter zu töten, um dies zu verhindern.","sz":null,"k":"yellow","box":[309.3,493.3,541.7,577.2],"p":65,"i":13,"sec":"wohnung-der-familie-jones"},{"t":"card","x":"<b>Wenn Felicia einigermaßen stabil ist</b>, berichtet sie, sie fühle sich bei Dr. Langstone, der ihre Fähigkeiten sieht und versteht, sicher. Nach den Sitzungen gehe es ihr besser. Bittet man sie, <b>in Ruhe zu überdenken, was Langstone darin tatsächlich sagt</b>, wird ihr klar, dass er ihre Gedanken über sich selbst und ihre Tochter vergiftet hat.","sz":null,"k":"yellow","box":[309.3,586.4,541.7,695.2],"p":65,"i":14,"sec":"wohnung-der-familie-jones"}],"size":[595.276,841.89]},"66":{"tab":"","blocks":[{"t":"threat","stars":"★★★","name":"FELICIA","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 5 / IHREN GEIST HEILEN 4 / DEN VERSTAND VERLIEREN 4","items":["<b>Wut-Göttin</b>: Wenn sie die Szene betritt, gib ihr <t>Wut 2</t>.","<b>Dämonischer Schutz</b>: Wenn man sich Felicia oder Mira nähert oder auf sie zielt, drängt eine unsichtbare Kraft die Betreffenden zurück oder aus dem Raum, so dass man erst <b>Ein Risiko eingehen</b> muss.","<b>Vor dem Ausrasten</b>: Wenn <i>den Verstand verlieren</i> das Maximum erreicht, verletzt sie sich selbst oder Mira (<b>Etwas Schreckliches geschehen lassen</b>).","Jemanden mit unsichtbarer Kraft schlagen oder stoßen (<t>gebrochener Arm 3</t> oder <t>gebrochenes Bein-3</t>)","Jemanden mit einem Schutzzeichen belegen, damit er sich ihr, der kleinen Mira oder dem Raum nicht nähern kann (<t>zurückgedrängt 3</t>)","Jemanden mit ihrer dämonischen Visage zu Tode erschrecken (<t>Herzrasen 2</t>)","Ausflippen und sich noch mehr aufregen (indem sie sich selbst <t>rasend 2</t> oder <t>verzweifelt 2</t> verleiht)"],"box":[102.6,57.5,133.2,69.5],"desc":"Zunächst scheint Felicia eine ganz normale Mutter unter Schlafentzug zu sein, in bequemer Kleidung und mit einer Mähne ungekämmten roten Haares. Wenn sie die Macht Palden Lhamos anzapft, nimmt sie eine schreckliche Gestalt an: Ihre Haut färbt sich blau, ihr Haar geht in Flammen auf, und auf ihrer Stirn öffnet sich ein drittes Auge.","p":66,"i":0,"sec":"wohnung-der-familie-jones"},{"t":"h","x":"PRIVATKLINIK VON HEILUNG FÜR DIE GEBROCHENEN","sz":16.0,"box":[333.9,63.9,521.8,96.9],"p":66,"i":1,"skip":true,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"ro","x":"Ihr schaudert, als ihr das Büro des Psychiaters betretet. Zwei bequeme Sitzgelegenheiten, die sich gegenüberstehen, lassen euch an Patient:innen denken, die sich bei einem Heißgetränk ihr Leid von der Seele reden. Schock, Verrat, Geheimnisse, unaussprechliche Fantasien – diese Mauern haben schon alles erlebt. Was würdet ihr dem Therapeuten sagen, wenn ihr in diesem Stuhl säßet? Dunkle Gedanken tauchen in eurem Hinterkopf auf und erinnern euch daran, wie ihr versagt habt, nicht gut genug seid, die ganze Zeit und in jeder Hinsicht. Ihr fühlt euch, wie sich alle Patient:innen vor euch gefühlt haben müssen: unrettbar gebrochen. Der Unterschied ist, dass ihr nicht darüber redet. Vielleicht sollten manche Dinge besser ungesagt bleiben.","sz":9.0,"box":[317.5,99.3,538.9,302.7],"p":66,"i":2,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"p","x":"Heilung für die Gebrochenen hat viele Mitglieder in der ganzen Stadt. Jedes betreibt eine eigene Privatklinik und erhält Überweisungen von den Helplines der Organisation. Hier sind einige Namen, auf die das Team bei der Suche nach Therapeut:innen von Heilung für die Gebrochenen stoßen könnte:","sz":9.5,"box":[309.0,311.7,541.2,383.7],"p":66,"i":3,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"p","x":"• <b>Dr. Selma Perrin</b>, die mit Martha Ellis (<i>Der sanfte Tod</i>) gearbeitet hat, ist eine teure Psychiaterin und Psychoanalytikerin, die in einer erstklassigen Privatpraxis in der Innenstadt arbeitet.","sz":9.5,"box":[309.0,395.2,539.5,442.2],"p":66,"i":4,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"p","x":"• Jeden anschreien, der versucht, das Kinderzimmer zu betreten, und dabei blau werden • Jemanden warnen, sich ihrer Tochter nicht zu nähern","sz":9.0,"box":[62.4,428.6,270.8,473.6],"p":66,"i":5,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"p","x":"• <b>Dr. Archibald Tennant</b>, der Maximilian Drake (<i>Kirmes der Maschinen</i>) beraten hat, ist ein traditioneller Psychiater mit einer Klinik in der Altstadt, der oft die Beratungsstellen der Organisation betreut.","sz":9.5,"box":[309.0,450.9,541.2,497.9],"p":66,"i":6,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"}],"size":[595.276,841.89]},"67":{"tab":"","blocks":[{"t":"p","x":"• <b>Dr. Drew Langstone</b>, Felicia Jones‘ Therapeut, hält Sitzungen in einer Klinik ab, die an seine Wohnung in einem der Arbeiterviertel angrenzt.","sz":9.5,"box":[53.9,62.5,279.0,97.0],"p":67,"i":0,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"p","x":"• Die <b>Polizeipsychologin Dr. Tracy Wong</b> hilft Mitarbeiter:innen der Strafverfolgungsbehörden und trifft sich mit ihnen in ihren Revieren. Sie ist die, die am ehesten Officer Das trifft und hat mit Sicherheitsmann Ruben Stone gearbeitet (s. S. <u>Der misslungene Golem).</u>","sz":9.5,"box":[53.9,105.7,286.0,177.7],"p":67,"i":1,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"p","x":"• Die Lebens- und Ernährungsberaterin <b>Augusta Summers</b> hat in der Vorstadt angefangen, nun aber in der Innenstadt einen wachsenden Kundenstamm.","sz":9.5,"box":[53.9,186.3,282.4,220.8],"p":67,"i":2,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"p","x":"• <b>Pater Brian Kelly</b>, ein Priester, der in einer örtlichen Kirche die Beichte abnimmt.","sz":9.5,"box":[53.9,229.5,286.2,251.5],"p":67,"i":3,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"p","x":"• <b>Dr. Lauren White</b>, Sozialpsychologin in den Elendsvierteln.","sz":9.5,"box":[53.9,260.2,285.3,282.2],"p":67,"i":4,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"sh","x":"<b>AUF DER SUCHE NACH RAT</b>","sz":10.0,"box":[54.3,290.1,200.8,300.1],"p":67,"i":5,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"p","x":"Wenn ein SC eine der Therapeut:innen als Patient:in aufsucht, spielt einen Teil der Therapiesitzung. Dies sollte dem SC Gelegenheit geben, seine innere Welt darzulegen: seine Konflikte, seine Fragen, seine Zweifel, seinen Schmerz – und ihm zugleich eine Menge Sendezeit verschaffen. <b>Dies spannt den Rahmen für kommende Konflikte mit Dr. Krystal Knight (und dem Fischerkönig) auf.</b>","sz":9.5,"box":[53.9,305.7,280.8,402.8],"p":67,"i":6,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"p","x":"Die Therapeut:innen von Heilung für die Gebrochenen sind äußerst intelligent und abgeklärt. Wenn der SC der Therapeut:in nicht misstraut oder nicht auf der Hut ist, <b>spiele sie als ideale Zuhörer:in und Vertrauensperson,</b> die den SC durch den Nebel hindurch sieht und ihn nicht für das verurteilt, was er ist. Die Therapeut:in wird dem SC keine Ideen aufzwingen, sondern zuhören, vor sich hin summen, nicken und Fragen stellen, um ihn zum Reden zu bringen.","sz":9.5,"box":[53.9,411.3,284.3,520.8],"p":67,"i":7,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"p","x":"Wenn der SC um Lebenshilfe bittet, stelle eine tiefgehende, offene Frage wie „Haben Sie das Gefühl, dass das, was in Ihnen steckt, wirklich ein Teil von Ihnen ist?“ oder „Wer ist Ihrer Meinung nach für das verantwortlich, was Ihnen passiert?“ Die Therapeut:in muss nicht offen über ihre Ansichten sprechen, um den SC mit Selbstzweifeln und Selbsthass zu infizieren – wie beim Teufelsspiegel reicht die Ar, wie sie Dinge zurückspiegelt. Nachdem der SC gegangen ist und etwas Zeit hatte, über die Sitzung nachzudenken, aktiviere die Spezialaktion <b>Dunkle Gedanken</b> der Therapeut:in.","sz":9.5,"box":[53.9,529.5,286.1,664.1],"p":67,"i":8,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"sh","x":"<b>AUF DER SUCHE NACH ANTWORTEN</b>","sz":10.0,"box":[54.3,677.6,251.2,687.6],"p":67,"i":9,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"p","x":"Auf der Suche nach Antworten stößt das Team auf Widerstand. Die Therapeut:in wird ihm aus dem Weg gehen oder die Sprechstundenhilfe wird die SC am Betreten hindern. Sie könnte auch Sicherheitsdienst oder Polizei rufen (Bedrohungsprofile s. 286).","sz":9.5,"box":[53.9,693.2,284.4,752.7],"p":67,"i":10,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"p","x":"<b>Wenn die SC die Therapeut:in zu fassen bekommen, ist es schwierig, sie direkt zu befragen.</b> Mit ihrer Spezialaktion <b>Hmmm</b> kann sie Fragen ausweichen und vermeiden, dass man in einem Gespräch <b>Nachforschungen</b> anstellt. Der Schutz, den die Spezialaktion <b>Hmmm</b> bietet, reicht tief in die Psyche der Therapeut:in, und kann selbst eingesetzt werden, wenn telepathisch gefragt wird (ihr Geist antwortet mit einer Frage). Um die Geheimnisse zu lüften, muss das Team die Aktion umgehen. Sind keine Mentalist:innen, Psycholog:innen oder Hellseher:innen im Team, könnte die Suche nach einer Lösung Anlass einer weiteren Szene sein (s. S. <b>Heilige und Hellseher</b>, S. 72). Die Therapeut:in, sofern das Team ihren Geist nicht gebrochen hat, wird nicht zugeben, dass das Ziel von Heilung für die Gebrochenen darin besteht, Risse zu verletzen. Sie verharmlost und vertritt weiter die Position der Organisationen. Die Wahrheit klingt zwischen den Zeilen und dem, was sie nicht sagt, durch.","sz":9.5,"box":[309.0,62.6,541.8,297.0],"p":67,"i":11,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"p","x":"<b>Die nachstehenden Informationen kann das Team auch auf andere Weise erlangen</b>: indem es die Therapeut:in beschattet und verfolgt, in ihr Büro einbricht, Patient:innen befragt (s. S. Textkasten Der Gefängnisbesuch), über Heilung für die Gebrochenen nachforscht usw.","sz":9.5,"box":[309.0,305.8,532.3,377.7],"p":67,"i":12,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"sh","x":"<b>ÜBER HEILUNG FÜR DIE GEBROCHENEN</b>","sz":10.0,"box":[309.4,391.3,525.7,401.3],"p":67,"i":13,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"card","x":"Heilung für die Gebrochenen ist eine Therapeut:innenorganisation, die versucht, Risse zu beeinflussen. Sie behaupten, ihnen helfen zu wollen, mit ihrer Existenz als solche besser umzugehen.","sz":null,"k":"yellow","box":[309.3,412.7,541.7,484.1],"p":67,"i":14,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"card","x":"Offiziell handelt es sich bei der „Therapie“ von Heilung für die Gebrochenen um eine Form des „Spiegelns“, die darauf abzielt, Patient:innen ihre Lebenssituation vor Augen zu führen, damit sie Verantwortung dafür übernehmen können. In Wirklichkeit zeigt diese pervertierte Technik Patient:innen nur, was an ihnen und ihrem Dasein als Risse falsch, schlecht oder quälend ist, was sie veranlasst, negative Gefühle und zerstörerisches Verhalten sich oder anderen Rissen gegenüber zu entwickeln.","sz":null,"k":"yellow","box":[309.3,493.3,541.7,639.6],"p":67,"i":15,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"card","x":"Die Begründerin dieser Theorie ist <b>Dr. Esther Monahan</b>.","sz":null,"k":"yellow","box":[309.3,648.9,541.7,682.6],"p":67,"i":16,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"}],"size":[595.276,841.89]},"68":{"tab":"","blocks":[{"t":"sh","x":"<b>ÜBER DR. ESTHER MONAHAN</b>","sz":10.0,"box":[54.3,62.8,213.6,72.8],"p":68,"i":0,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"card","x":"Dr. Esther Monahan leitet seit Jahrzehnten die <b>Städtische Anstalt für kriminelle Geisteskranke</b> (kurz <u>„Die Anstalt“),</u> müsste weit über neunzig sein, und hat sich noch nicht zur Ruhe gesetzt. Sie ist gewollt unverheiratet und kinderlos und hat ihr Leben ganz ihrer Arbeit gewidmet.","sz":null,"k":"yellow","box":[54.1,82.4,286.6,178.8],"p":68,"i":1,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"card","x":"<b>Recherche lässt das Team auf ihre Veröffentlichungen zum Thema Riss-Sein stoßen, was in den letzten Jahren ihr Schwerpunkt ist.</b> Behandle einen Riss, der die Texte liest, wie jemanden, der an einer Therapie-Sitzung von Heilung für die Gebrochenen teilgenommen und dabei <b>Dunkle Gedanken</b> entwickelt.","sz":null,"k":"yellow","box":[54.1,188.1,286.6,284.3],"p":68,"i":2,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"card","x":"<b>Aufgrund ihres Alters sind viele Unterlagen, etwa die Geburtsurkunde, nicht im System.</b> Weitere Informationen liegen möglicherweise (physisch oder digital) bei der <u>Historischen Gesellschaft</u> der Stadt.","sz":null,"k":"yellow","box":[54.1,293.5,286.6,364.9],"p":68,"i":3,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"sh","x":"<b>ÜBER DIE THERAPEUTIN</b>","sz":10.0,"box":[54.3,378.1,189.2,388.1],"p":68,"i":4,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"card","x":"<b>Die Therapeutin bewahrt die Akten ihrer ehemaligen Patient:innen</b> auf einem Computer oder in einem Aktenschrank auf. Die Aufzeichnungen stimmen mit dem überein, was das Team bereits über die Opfer weiß. Weiteres Studium der Dokumente verrät die Gesinnung der Therapeutin (s. u.) So lässt sich enthüllen, dass ein anderer NSC (oder SC) Opfer von Heilung für die Gebrochenen ist, wie zum Beispiel Ruben Stone <u>(Der misslungene Golem).</u>","sz":null,"k":"yellow","box":[54.1,395.7,286.6,529.6],"p":68,"i":5,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"card","x":"Leitende Mitglieder von Heilung für die Gebrochenen erstattet einander bei einer wöchentlichen <u>Supervision</u> in der Altstadt-Universität (oder, wenn du die Szene überspringst, direkt in der <u>Anstalt)</u> Bericht.","sz":null,"k":"yellow","box":[54.1,538.8,286.6,610.0],"p":68,"i":6,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"card","x":"<b>Wenn man die Psyche der Therapeutin mit mythischen Mitteln erforscht</b>, wird man einen tief verwurzelten Hass auf Risse und die feste Überzeugung finden, dass alle Risse ohne Ausnahme eine Perversion sind.","sz":null,"k":"yellow","box":[54.1,619.2,286.6,690.6],"p":68,"i":7,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"card","x":"<b>Jenseits des Nebels</b> befindet sich eine symbolische Glasscherbe im gefrorenen Herzen der Therapeutin. Man kann ihre Herkunft auf die <u>Supervision</u> oder die <u>Anstalt</u> zurückführen.","sz":null,"k":"yellow","box":[54.1,699.8,286.6,758.6],"p":68,"i":8,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"h","x":"THERAPEUT:IN VON HEILUNG FÜR","sz":12.0,"box":[317.5,61.6,481.4,73.6],"p":68,"i":9,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"threat","stars":"★★★","name":"DIE GEBROCHENEN","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 2 / GEIST BRECHEN 4 / ENTLARVEN 4","items":["<b>Dunkle Gedanken</b>: Wer Zeit hatte, nachzudenken, worüber mit der Therapeut:in gesprochen wurde, erhält <t>Selbstzweifel 1</t> oder <t>ungutes Gefühl 1</t> (jedes Mal, wenn diese Aktion ein Ziel betrifft, unabhängig von der Quelle, steigt die Stufe des Zustands um 1 auf <t>Angst 2</t>, <t>Verzweiflung 3</t>, <t>Selbsthass 4</t> usw.)","<b>Hmmm</b>: Befragt man bei <b>Nachforschungen</b> eine Therapeut:in oder tritt man ihr gegenüber aggressiv auf, erhält man <t>Selbstzweifel 2</t>, während sie vor sich hin summt und eine Frage stellt, etwa: » „Hmmm. Warum glauben Sie, dass hier Aggression nötig ist?„ » „Hmmm. Geht es hier um mich oder vielmehr um Ihren Vater/Ihre Mutter?„ » „Hmmm. Woher kommt dieser Wunsch, alles zu wissen? Was meinen Sie?„","<b>Sublimierungstechniken</b>: Wenn die Therapeut:in einen mentalen oder emotionalen Zustand erhält, reduziert sich dessen Stufe um 1.","<b>Aufatmen</b>: Wenn <i>Entlarven</i> das Maximum erreicht, kann die Therapeut:in <b>Dunkle Gedanken</b> nicht mehr anwenden. Wenn das Maximum von <i>Geist brechen</i> erreicht ist, kann die Therapeut:in weder <b>Hmmm</b> noch <b>Sublimationstechniken</b> anwenden.","Fragen stellen, die Gesprächspartner:innen an sich selbst zweifeln lassen oder ein schlechtes Gefühl geben (<t>Selbstzweifel</t> oder <t>ungutes Gefühl</t> 1 oder 2)","Den Sicherheitsdienst (neue Bedrohung: Streifenpolizist:innen/Wachleute, s. 286) und später ihre Anwältin (Firmenanwältin, s. 288) rufen","Jemanden analysieren und die emotionale Situation der Person richtig einschätzen (<t>verletzlich 1</t>)","Jemanden hypnotisieren, indem man zunächst dessen Aufmerksamkeit erregt und dann unterbewusste Befehle erteilt (<t>hypnotisiert 2</t>)","Durch eine Hintertür fliehen (I<b>hnen etwas verweigern, das sie wollen</b>)","Aufmerksam zuhören"],"box":[413.4,75.5,444.0,87.5],"p":68,"i":10,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"}],"size":[595.276,841.89]},"69":{"tab":"","blocks":[{"t":"h","x":"DER GEFÄNGNISBESUCH","sz":14.0,"box":[65.2,61.0,178.0,75.0],"p":69,"i":0,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"p","x":"Beim Sammeln von Informationen über Heilung für die Gebrochenen kann es sein, dass das Team mit ehemaligen Feind:innen und Opfern der Therapeut:innenorganisation Kontakt aufnehmen muss, z. B. mit der Jazzsängerin Martha Ellis (Banshee) oder dem verrückten Wissenschaftler Maximilian Drake (Hephaistos). So könnte auch eine Nemesis in den Aufzeichnungen einer Therapeut:in auftauchen und das Team zu einem unangenehmen Treffen zwingen.","sz":9.0,"box":[65.2,87.5,272.8,204.5],"p":69,"i":1,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"p","x":"Je nachdem, wie vorherige Begegnungen ausgingen, befindet sich die Feind:in des Teams vielleicht in einem physischen oder spirituellen Gefängnis (wie der Hölle oder in der Anderswelt) und hegt wahrscheinlich einen Groll gegen das Team. Wenn die Feind:in Zeit zum Nachdenken hatte (und der Einfluss der Organisation abgeklungen), ist sie vielleicht zugänglicher oder einsam und deshalb gesprächsbereit.","sz":9.0,"box":[65.2,213.2,274.2,306.2],"p":69,"i":2,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"p","x":"Das Treffen des Teams mit seiner alten Feind:in könnte die Möglichkeit bieten, alte Wunden aufzureißen, Gefühle auszudrücken, Dinge zu klären und/ oder eine neue Perspektive auf vergangene Ereignisse zu bekommen. Das ist als Gelegenheit zum Rollenspiel und nicht als Herausforderung gedacht, daher sind Regeln nicht erforderlich.","sz":9.0,"box":[65.2,314.8,269.3,395.8],"p":69,"i":3,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"p","x":"Feind:innen, die in der <u>Anstalt</u> sitzen, könnten einen Besuch bedeuten, der mit Rollenspiel beginnt und mit Action endet. Solche NSC stehen unter massivem Einfluss von Heilung für die Gebrochenen.","sz":9.0,"box":[65.2,404.5,268.6,449.5],"p":69,"i":4,"sec":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"t":"h","x":"SUPERVISION","sz":16.0,"box":[79.7,482.0,170.0,498.0],"p":69,"i":5,"skip":true,"sec":"supervision"},{"t":"ro","x":"Das Klackern teurer Schuhe auf Marmorböden hallt durch die breiten Gänge und löst bei euch leichte Angst aus. Ihr geht eine breite Steintreppe mit rotem Teppich bis zu der Kreuzung mehrerer Flure hinauf und öffnet eine hohe hölzerne Doppeltür, die mit dekorativen Schnitzereien verziert ist. Dahinter stört einen Kreis distinguierter Personen mittleren Alters, die ins Gespräch vertieft sind. Sie verstummen, die Augen sind auf euch gerichtet. „Können wir Ihnen behilflich sein?„","sz":9.0,"box":[62.4,500.4,283.8,628.2],"p":69,"i":6,"sec":"supervision"},{"t":"p","x":"Das Team möchte vielleicht weitere Antworten finden, wenn es von der ersten getroffenen Therapeut:in, nicht genug erfahren hat. Eventuell wollen die SC das Treffen stürmen und Therapeut:innen von Heilung für die Gebrochenen gefangen nehmen.","sz":9.5,"box":[309.0,59.9,539.0,119.4],"p":69,"i":7,"sec":"supervision"},{"t":"p","x":"Sich einer Handvoll (Größenfaktor 1) oder einem Dutzend (Größenfaktor 2) von berührten Therapeut:innen zu stellen mag einfach klingen, ist es aber nicht. Sie könnten sich auf schwache Teammitglieder stürzen, Schwächen analysieren und ihren geheimen, unausgesprochenen Schmerz offenbaren (oder sich dem nähern) und damit ausschalten. Außerdem hat die Gruppe, die hier oft labile Personen befragt, nebenan ein Team <b>Psychiatriepfleger:innen</b> in Bereitschaft, die sie rufen kann, wenn Dinge aus dem Ruder laufen (du kannst das Team vorwarnen und zulassen, die Therapeut:innen daran zu hindern, die Pfleger:innen zu alarmieren, wenn du es einfacher machen möchtest).","sz":9.5,"box":[309.0,128.1,540.7,287.6],"p":69,"i":8,"sec":"supervision"},{"t":"p","x":"Die Mitglieder der Therapeut:innengruppe können dieselben Hinweise geben, die unter <u>Die Privatklinik von Heilung für die Gebrochenen</u> beschrieben wurden und zu Dr. Monahan und <u>der Anstalt</u> führen. Gelingt es dem Team, die Gruppe zu unschädlich machen oder eines der leitenden Mitglieder festzusetzen, kannst du es mit zusätzlichen Hinweisen belohnen. Wenn die Therapeut:innen und Psychiatriepfleger:innen das Team überwältigen, wachen die SC als Patient:innen auf, eingesperrt in einer Gummizelle im Keller <u>der Anstalt</u> sind (s. S. dort, Einzelhaft).","sz":9.5,"box":[309.0,296.3,538.3,430.8],"p":69,"i":9,"sec":"supervision"},{"t":"card","x":"<b>Einige der erfahrensten Therapeut:innen von Heilung für die Gebrochenen kennen Dr. Monahan persönlich</b> und haben bei der Erarbeitung ihrer Theorie mitgeholfen. Die anderen sind diesem Genie, das in der <u>Anstalt</u> hinter verschlossenen Türen arbeitet, nie begegnet.","sz":null,"k":"yellow","box":[309.3,436.9,541.7,520.7],"p":69,"i":10,"sec":"supervision"},{"t":"card","x":"Ein Eindringen und intensive Suche in den Gedanken einer der leitenden Therapeut:innen könnte ans Licht bringen, was die Therapeut:in mit aller Macht zu verdrängen versucht: <b>Dr. Monahan ist schon seit Jahren tot.</b>","sz":null,"k":"yellow","box":[309.3,529.9,541.7,601.1],"p":69,"i":11,"sec":"supervision"},{"t":"p","x":"Einmal pro Woche veranstalten <b>Dr. Selma Perrin</b> und <b>Dr. Archibald Tennant</b> (oder andere Therapeuten, die du als leitende Mitglieder von Heilung für die Gebrochenen nutzen möchtest) ein Supervisionstreffen, bei dem Therapeut:innen über ihre Fortschritte bei ihren Riss-Fällen berichten und Ratschläge von Kolleg:innen erhalten. Das Treffen findet in der Altstadt-Universität statt, in den prunkvoll verzierten Marmorsälen der psychologischen Fakultät.","sz":9.5,"box":[53.9,637.2,285.2,746.7],"p":69,"i":12,"sec":"supervision"}],"size":[595.276,841.89]},"70":{"tab":"","blocks":[{"t":"threat","stars":"★★★","name":"PSYCHIATRIEPFLEGER:INNEN","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 4 / ÜBER- ZEUGEN 5","items":["<b>Kollektiv</b>: Dieses Kollektiv hat einige Mitglieder und einen Größenfaktor von 1.","<b>Fies</b>: Wenn die Psychiatriepfleger:innen einen sozialen oder emotionalen Zustand bekommen, der sie nicht fieser macht, reduziert sich die Stufe um 1.","<b>Abnorm stark</b>: Wenn die Pfleger:innen physischen Schaden oder einen Zustand, der sie schwächt, erleiden und der sich durch Stärke oder Ausdauer vermeiden lässt, reduziert sich dessen Stufe um 1.","<b>Schlafenszeit</b>: Einmal pro Szene pro Größenfaktor zieht eine Psychiatriepfleger:in als harte Aktion eine Ein-Schuss-Betäubungspistole und feuert sie auf eine widerspenstige Patient:in ab (<t>sediert 4</t>).","Manuell oder mit einer Zwangsjacke ruhigstellen (<t>gefesselt 3</t>)","Injektion eines starken Beruhigungsmittels in gefesselte Patient:innen (Umwandlung des <t>gefesselt</t>- in einen <t>sediert</t>-Zustand der gleichen Stufe)","Die Bitten von Patient:innen ignorieren (2 Stufen von jedem Überzeugen-Zustand entfernen)","Patient:innen warnen, sich zu benehmen, sonst …","Sich neben gefesselte Patient:innen stellen und eine Spritze hochhalten, aus der Flüssigkeit spritzt"],"box":[210.5,56.7,241.1,68.7],"desc":"Die Psychiatriepfleger:innen von Heilung für die Gebrochenen sind extrem groß und muskulös und tragen die weißen Uniformen der städtischen Anstalt für kriminelle Geisteskranke. Sie zeigen keinerlei Manieren am Krankenbett oder eine pflegerische Ausbildung. Es scheint, als wären sie angeheuerte Schläger, die vorgegebene Sprüche aufsagen.<br><br>Ziehe in Erwägung, den Größenfaktor dieser Bedrohung auf 2 zu erhöhen, wenn das Team mehr als vier Mitglieder hat oder starke Kämpfer:innen dabei sind.","p":70,"i":0,"sec":"supervision"},{"t":"h","x":"DER MISSLUNGENE GOLEM","sz":16.0,"box":[333.1,74.1,511.0,90.1],"p":70,"i":1,"skip":true,"sec":"der-misslungene-golem"},{"t":"ro","x":"Menschen strömen panisch schreiend aus den Türen des Kaufhauses. Viele von ihnen, vor allem die hinteren, sind mit einer Schicht graubraunen Lehms bedeckt. Dahinter seht ihr eine Schlammwelle, die durch die Gänge schwappt und Schaufensterpuppen und Kleiderständer umwirft, die versinken, als wäre es Treibsand. Ihr hört das Gebäude kreischen und stöhnen und bemerkt mehrere Brüche entlang der Decke, die sich ausweiten. Was könnte so eine Verwüstung verursachen? Dann hört ihr einen Schrei aus dem Inneren.","sz":9.0,"box":[317.5,92.5,538.9,231.1],"p":70,"i":2,"sec":"der-misslungene-golem"},{"t":"p","x":"Ein weiteres Opfer von Heilung für die Gebrochenen, <b>Ruben Stone</b> (Golem von Prag), wurde im Kaufhaus von Depression und Verzweiflung überwältigt. Dieser emotionale Zustand löste seine Kräfte aus, und nun verwandelt er das Fundament des Einkaufszentrums in das gleiche Material, aus dem er besteht: Lehm. Ruben ist sich der Folgen seines Handelns nur halb bewusst, und die andere Hälfte ist so verzweifelt, dass sie bereit ist, mit dem Kaufhaus unterzugehen.","sz":9.5,"box":[309.0,240.1,540.2,349.6],"p":70,"i":3,"sec":"der-misslungene-golem"},{"t":"p","x":"Wenn du diesen Fall als One-Shot leitest, bietet diese Szene dem Team ein zweites Opfer von Heilung für die Gebrochenen. Andernfalls kannst du sie als Actionszene verwenden, um das Tempo der Folge zu erhöhen, wenn etwas Schwung fehlt.","sz":9.5,"box":[309.0,358.2,541.5,417.7],"p":70,"i":4,"sec":"der-misslungene-golem"},{"t":"p","x":"Jemand kann das Team auf den Tatort aufmerksam machen: ein Nebencharakter ist vor Ort, die Polizei (möglicherweise die Beamten Das und Quinn) oder jemand, der Ruben oder den Ruf des Teams kennt. Die SC könnten sich zufällig im Einkaufszentrum aufhalten, wenn das Chaos ausbricht.","sz":9.5,"box":[309.0,426.4,536.1,498.4],"p":70,"i":5,"sec":"der-misslungene-golem"},{"t":"sh","x":"<b>DIE SITUATION</b>","sz":10.0,"box":[309.4,512.0,393.0,522.0],"p":70,"i":6,"sec":"der-misslungene-golem"},{"t":"p","x":"• <b>Ruben Stone</b> sitzt in den Umkleidekabinen des Kaufhauses und sondert große Mengen magischen, graubraunen Lehms ab, der leblose Materie langsam in ähnlichen, nichtmagischen Schlamm verwandelt (Steine und Sedimente verwandeln sich schneller, gefolgt von Erzen wie Eisen und Kupfer. Tote organische Materie wie Holz und Kleidung braucht länger.). Der nichtmagische Schlamm erleichtert den Fluss des magischen Lehms. Die Schläfer:innen glauben, es sei ein Abwasserkanal oder Zementrohr geplatzt (die Art, wie Bauarbeiter:innen sie verwenden). Aufmerksame Schläfer:innen bemerken eine Person, von der sie glauben, sie versuche das Leck zu reparieren.","sz":9.5,"box":[309.0,530.4,541.3,689.9],"p":70,"i":7,"sec":"der-misslungene-golem"},{"t":"p","x":"• <b>Viele hilflose Kund:innen</b> befinden sich im Kaufhaus, wissen nicht, was passiert ist, stecken fest, sind verletzt oder suchen nach jemandem oder etwas.","sz":9.5,"box":[309.0,698.6,540.8,733.1],"p":70,"i":8,"sec":"der-misslungene-golem"}],"size":[595.276,841.89]},"71":{"tab":"","blocks":[{"t":"p","x":"• Der Lehm hat die Böden an einigen Stellen aufgefressen und <b>Lachen aus klebrigem Matsch</b> gebildet, die wie Treibsand wirken. An anderen Stellen hat sich der Lehm in die Fundamente des Kaufhauses gefressen, so dass diese ungleichmäßig absinken, was zu <b>Spalten und Brüchen im Gebäude</b> führt. Wenn der Schlamm nicht abfließt, wird das Kaufhaus zusammenbrechen und alle darin begraben.","sz":9.5,"box":[53.9,59.9,285.5,156.9],"p":71,"i":0,"sec":"der-misslungene-golem"},{"t":"card","x":"<b>Ruben Stone ist Wachmann im Kaufhaus.</b> Das kann man herausfinden, indem man jemanden findet, der ihn beim Betreten des Ladens gesehen hat, oder indem man durch den Schlamm seinen Ausweis in der Kleidung ertastet.","sz":null,"k":"yellow","box":[54.1,164.7,286.6,236.2],"p":71,"i":1,"sec":"der-misslungene-golem"},{"t":"card","x":"<b>Ruben Stone war Patient bei Dr. Tracy Wong,</b> wie aus seinem Telefonprotokoll, den Patientenakten der Therapeutin oder seiner Mitarbeiterakte bei der Sicherheitsfirma, für die er arbeitet, hervorgeht.","sz":null,"k":"yellow","box":[54.1,245.1,286.6,316.5],"p":71,"i":2,"sec":"der-misslungene-golem"},{"t":"card","x":"<b>Er hat mit schweren Depressionen und Suizidgedanken zu kämpfen.</b> Dadurch lassen seine Kräfte nach, doch er ist zu apathisch, um sich darum zu kümmern.","sz":null,"k":"yellow","box":[54.1,325.7,286.6,384.5],"p":71,"i":3,"sec":"der-misslungene-golem"},{"t":"card","x":"<b>Jenseits des Nebels</b> hat der Golem drei leuchtende hebräische Buchstaben auf der Stirn: <b>תמא</b> (<i>e‘met</i>), was „Wahrheit“ bedeutet. Der rechte Buchstabe verblasst und lässt schließlich nur noch <b>תמ</b> (<i>met</i>) übrig, was „tot“ bedeutet. <b>In der Geschichte des Golems</b> verwandelte er sich nach dem Tod der menschlichen Form in den Lehm, aus dem er gemacht wurde.","sz":null,"k":"yellow","box":[54.1,393.7,286.6,502.6],"p":71,"i":4,"sec":"der-misslungene-golem"},{"t":"h","x":"SCHLAMMLAWINEN-EINKAUFSZENTRUM","sz":12.0,"box":[317.5,61.6,521.5,73.6],"p":71,"i":5,"sec":"der-misslungene-golem"},{"t":"threat","stars":"★★★","name":"VERLETZEN ODER UNSCHÄDLICH MACHEN 4 / ÜBER- ZEUGEN 5","spectra":"","items":["<b>Echte Helden</b>: Für jede Person, die das Team aus dem Schlammlawinen-Kaufhaus in Sicherheit bringt, gibst du <t>geräumt 1</t>. Wenn der Maximalwert von <i>Geräumt</i> erreicht ist, befinden sich keine Unbeteiligten mehr im Einkaufszentrum.","<b>Einsturz</b>: Wenn das <i>Einsturz</i>-Spektrum voll ist, stürzt das Gebäude ein, und alle darin befindlichen Personen sind <t>unter Trümmern begraben 5</t>.","<b>Suizidal</b>: Wenn die SC zum ersten Mal mit Ruben sprechen, gib ihm <t>suizidal 4</t>.","<b>Hergestellt aus Schlamm</b>: Wenn Ruben körperlichen Schaden oder einen schwächenden Zustand, der den Schlamm nicht trocknen oder eindämmen würde, erleidet, reduziert sich die Stufe um 3.","<b>Schlammbombe</b>: Wenn <i>Ruben verletzen</i> den Maximalwert erreicht, explodiert er, und das Schlammlawinen-Kaufhaus erleidet <t>Einsturz 3</t>.","Jemanden mit schwerem Schlamm bedecken oder in eine Pfütze ziehen (<t>im Schlamm feststeckend 3</t>)","Jemanden, der Ruben verärgert, schlagen und zurückschleudern (<t>atemlos 3</t>) oder mit Schlamm bespritzen (<t>im Schlamm feststeckend 3</t>)","Ruben wird wütend, explodiert und versprüht überall Schlamm (gib allen Anwesenden <t>im Schlamm feststeckend 3</t> und dem Einkaufszentrum <t>Einsturz 1</t>)","Brüche in den tragenden Wänden und der Decke (Schlammlawinen-Kaufhaus erleidet <t>Einsturz 2</t>)"],"box":[317.5,75.5,348.1,87.5],"p":71,"i":6,"sec":"der-misslungene-golem"},{"t":"card","x":"<b>Jenseits des Nebels und in der Geschichte des Golems</b> schuf ihn ursprünglich der Prager Maharal, um die jüdische Gemeinschaft Prags zu schützen. Dies steht mit Rubens Beruf in Verbindung und kann als Motivation dienen, um ihm aus seiner Depression herauszuhelfen.","sz":null,"k":"yellow","box":[54.1,511.8,286.6,595.6],"p":71,"i":7,"sec":"der-misslungene-golem"},{"t":"card","x":"<b>Wenn man ihn rettet und über die Sitzungen mit Dr. Tracy Wong befragt,</b> erkennt Ruben, dass sie die Depression vertieft hat, indem sie alles betonte, was in seinem Leben falsch lief.","sz":null,"k":"yellow","box":[54.1,604.8,286.6,663.6],"p":71,"i":8,"sec":"der-misslungene-golem"},{"t":"p","x":"• Auf eine unbeteiligte Person aufmerksam machen, die feststeckt, verletzt ist, sich verirrt hat, in Panik ist, klaut, neugierig ist usw. • Den Weg mit einer Schlammlawine blockieren","sz":9.0,"box":[317.5,476.6,527.9,521.6],"p":71,"i":9,"sec":"der-misslungene-golem"}],"size":[595.276,841.89]},"72":{"tab":"","blocks":[{"t":"h","x":"HEILIGE UND HELLSEHER:INNEN","sz":15.0,"box":[53.9,62.1,260.0,77.1],"p":72,"i":0,"sec":"der-misslungene-golem"},{"t":"p","x":"Wenn so viel geistige und emotionale Energie im Umlauf ist, möchte das Team vielleicht Risse- oder Schläfer-Fachleute anheuern, um die psychische Last zu tragen. Hier ein paar Möglichkeiten:","sz":9.5,"box":[53.9,82.8,277.7,129.8],"p":72,"i":1,"sec":"der-misslungene-golem"},{"t":"p","x":"Nicht alle Therapeut:innen der Stadt sind böse Psychos von Heilung für die Gebrochenen. <b>Geraldine Granger</b> (Schläferin) ist eine von vielen Therapeut:innen, die ihren Patient:innen wirklich helfen wollen. Geraldine weiß alles über Traumata und wie man sie überwindet. Sie hat diese Reise persönlich als auch als Reiseführerin viele Male gemacht. Risse bekommen bei ihr das Gefühl, dass sie sich mit ihnen identifizieren kann, auch ohne die Kräfte zu sehen. Die Probleme sind letztlich nur menschlich.","sz":9.5,"box":[53.9,138.5,286.1,260.5],"p":72,"i":2,"sec":"der-misslungene-golem"},{"t":"p","x":"Schwieriger ist Geraldine davon zu überzeugen, dass Heilung für die Gebrochenen böse ist. Eher wird sie herausfinden wollen, was im Leben der SC nicht stimmt, dass sie sich imaginäre Psychobösewichte ausdenken.","sz":9.5,"box":[53.9,269.1,286.1,316.1],"p":72,"i":3,"sec":"der-misslungene-golem"},{"t":"sh","x":"<b>GERALDINE GRANGER</b>","sz":12.0,"box":[65.1,350.7,199.4,362.7],"p":72,"i":4,"sec":"der-misslungene-golem"},{"t":"p","x":"<i>Verbündete</i>","sz":10.0,"box":[65.1,372.4,119.4,382.4],"p":72,"i":5,"sec":"der-misslungene-golem"},{"t":"h","x":"IDENTITÄT","sz":10.0,"box":[65.1,393.9,111.4,403.9],"p":72,"i":6,"sec":"der-misslungene-golem"},{"t":"p","x":"Ich bin ganz Ohr.","sz":9.0,"box":[65.1,408.6,131.5,417.6],"p":72,"i":7,"sec":"der-misslungene-golem"},{"t":"h","x":"STÄRKEN","sz":10.0,"box":[65.1,429.4,105.7,439.4],"p":72,"i":8,"sec":"der-misslungene-golem"},{"t":"card","x":"<b><i>Gute Zuhörerin</i></b>, <i>Ausgebildete Psychologin</i>, <i>Sozialarbeiterin</i>, <i>Fürsorge für andere</i>, <i>Bestärkende Worte</i>, <i>Positive Bestätigung</i>, <i>Patient:innendatenbank des Stadtkrankenhauses</i>, <i>Privatklinik</i>, <i>Medizinische Dienstleistungen</i>, <i>Motiviert durch Liebe</i>","sz":null,"k":"yellow","box":[65.4,442.9,272.2,501.1],"p":72,"i":9,"sec":"der-misslungene-golem"},{"t":"h","x":"SCHWÄCHEN","sz":10.0,"box":[65.1,512.9,122.0,522.9],"p":72,"i":10,"sec":"der-misslungene-golem"},{"t":"card","x":"<i>Aggressionen unterbinden</i>, <i>Ärztliche Schweigepflicht</i>, <i>Kann Übernatürliches nicht sehen</i>, <i>Gewalttätige Patient:innen</i>","sz":null,"k":"yellow","box":[65.4,526.5,271.3,560.4],"p":72,"i":11,"sec":"der-misslungene-golem"},{"t":"h","x":"THEMENVERBESSERUNG","sz":10.0,"box":[65.1,572.4,171.8,582.4],"p":72,"i":12,"sec":"der-misslungene-golem"},{"t":"p","x":"<b>Vertrauensperson:</b> Wenn du in der Drehpause deine Probleme mit Geraldine besprichst, erhältst du bei Vorbereitung auf die nächste Aktivität 5 statt 3 Momentum. Wenn du dich von einer vergangenen Aktivität erholst, entferne alle nicht dauerhaften psychologischen Zustände.","sz":9.0,"box":[65.1,587.1,269.6,656.1],"p":72,"i":13,"sec":"der-misslungene-golem"},{"t":"p","x":"Sucht das Team nach einem übersinnlichen Helfer, ist es am besten bei jemanden aufgehoben, der für den gutartigen Avatar Ganesha und seine tausend helfenden Hände arbeitet. Die Grundprämisse dieser Kampagne, die unter <b>Payne und andere Avatare</b> (s. S. 16) erklärt ist, lässt Ganesha und die meisten ihrer Risse das Team nicht unterstützen. Dafür sind sie von Natur aus hilfsbereite Freigeister, und unterlassene Hilfeleistung ist schlecht mit ihrem Mythos zu vereinbaren. Sie könnten versuchen, sich davor zu drücken, geben aber nach und spielen mit, wenn das Team hartnäckig ist.","sz":9.5,"box":[309.0,59.9,540.0,194.4],"p":72,"i":14,"sec":"der-misslungene-golem"},{"t":"p","x":"Eine Alternative ist der als <b>der Thaumaturg</b> bekannte Mystiker-Riss (Grigori Rasputin, persönlicher Heiler und Mystiker der letzten Zarenfamilie), der für im Industriegebiet lebende Risse leicht zu erreichen ist. Er verfügt über beeindruckende psychische Kräfte, manipuliert Gedanken genauso geschickt wie Messer und kann das Denken mehrerer Risse heilen, schützen, ergründen, ausschalten und sogar löschen.","sz":9.5,"box":[309.0,203.1,539.8,300.1],"p":72,"i":15,"sec":"der-misslungene-golem"},{"t":"p","x":"Der schrullige Mystiker im Trenchcoat arbeitet nicht umsonst. Er verlangt eine hohe Summe oder ein wertvolles Relikt. Problematisch ist seine fragwürdige Loyalität. Er würde seine eigene Haut retten und das Team dem Tod überlassen, wenn die Dinge zu gefährlich werden.","sz":9.5,"box":[309.0,308.8,536.0,380.8],"p":72,"i":16,"sec":"der-misslungene-golem"},{"t":"sh","x":"<b>DER THAUMATURG</b>","sz":12.0,"box":[320.3,412.3,434.7,424.3],"p":72,"i":17,"sec":"der-misslungene-golem"},{"t":"p","x":"<i>Verbündeter</i>","sz":10.0,"box":[320.3,434.1,378.5,444.1],"p":72,"i":18,"sec":"der-misslungene-golem"},{"t":"h","x":"IDENTITÄT","sz":10.0,"box":[320.3,455.5,366.6,465.5],"p":72,"i":19,"sec":"der-misslungene-golem"},{"t":"p","x":"Lasst Geld fließen, und ich werde die schlechten Träume fernhalten.","sz":9.0,"box":[320.3,470.3,511.8,491.3],"p":72,"i":20,"sec":"der-misslungene-golem"},{"t":"h","x":"STÄRKEN","sz":10.0,"box":[320.3,503.0,360.9,513.0],"p":72,"i":21,"sec":"der-misslungene-golem"},{"t":"card","x":"<b><i>Mächtiger Hellseher</i></b>, <i>Messerjonglage</i>, <i>Psychisches Trauma heilen</i>, <i>Bekommt sein Geld</i>, <i>Verstand zerquetschen</i>, <i>Schützende psychische Barriere</i>, <i>Gedanken und Erinnerungen lesen</i>, <i>Trenchcoat</i>, <i>Unterweltprivatier</i>, <i>Hypnotischer Blick</i>","sz":null,"k":"yellow","box":[320.5,516.7,515.2,574.6],"p":72,"i":22,"sec":"der-misslungene-golem"},{"t":"h","x":"SCHWÄCHEN","sz":10.0,"box":[320.3,586.5,377.2,596.5],"p":72,"i":23,"sec":"der-misslungene-golem"},{"t":"card","x":"<i>Wendet sich gegen Verbündete</i>, <i>Übersteigt meine Gehaltsklasse</i>, <i>Wechselnde Loyalitäten</i>, <i>Unzufriedene frühere Kunden</i>","sz":null,"k":"yellow","box":[320.5,600.2,515.5,634.2],"p":72,"i":24,"sec":"der-misslungene-golem"},{"t":"h","x":"THEMENVERBESSERUNG","sz":10.0,"box":[320.3,646.0,427.0,656.0],"p":72,"i":25,"sec":"der-misslungene-golem"},{"t":"p","x":"<b>Bezahlen</b>: Gib 2 Momentum als Zahlung an den Thaumaturgen, um alle verbrannten Stärken dieses Themas wiederherzustellen. Jedes Mal, wenn du die Verbesserung aktivierst, steigen die Kosten um 1.","sz":9.0,"box":[320.3,660.8,528.3,705.8],"p":72,"i":26,"sec":"der-misslungene-golem"},{"t":"p","x":"<b>Psychisches Kraftpaket</b>: Wenn du mit Stärken dieses Themas <b>Das Blatt wendest</b>, hat der Effekt automatisch +1 Stufe.","sz":9.0,"box":[320.3,717.3,513.7,750.3],"p":72,"i":27,"sec":"der-misslungene-golem"}],"size":[595.276,841.89]},"73":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 2:","sz":14.0,"box":[53.9,61.9,122.1,75.9],"p":73,"i":0,"skip":true,"sec":"schicht-2-ein-kuehler-empfang"},{"t":"h","x":"EIN KÜHLER EMPFANG","sz":23.0,"box":[53.9,84.2,265.7,107.2],"p":73,"i":1,"skip":true},{"t":"h","x":"DIE ANSTALT","sz":16.0,"box":[79.7,120.8,162.7,136.8],"p":73,"i":2,"skip":true,"sec":"die-anstalt"},{"t":"ro","x":"Während ihr den Hügel hochfahrt, verschlechtert sich das Wetter. Die Wolken drängen sich wie schwarze Schafe aneinander, und die Temperatur fällt. Bald verwandelt sich der Regen in Schneematsch und dann in Schneeflocken, die sich sacht auf euer Auto legen. Oben, zwischen den Nadelbäumen, seht ihr ein bedrohliches altes Herrenhaus, das von Schnee bedeckt ist. Als ihr euch der städtischen Anstalt für kriminelle Geisteskranke nähert, zucken hinter ihr Blitze auf und erhellen sie wie ein märchenhaftes Eisschloss.","sz":9.0,"box":[62.4,139.2,283.8,277.8],"p":73,"i":3,"sec":"die-anstalt"},{"t":"p","x":"Die Städtische Anstalt für kriminelle Geisteskranke, auch einfach „die Anstalt“ genannt, ist ein dreistöckiges rotes Backsteingebäude, das auf einem abgelegenen, bewaldeten Hügel am Stadtrand liegt und auf einen friedlichen Vorort blickt. Wie es sich für einen „Palast“ gehört, dienen die Anstalt und alle Menschen darin der Schneekönigin, Dr. Krystal Knight. Auch wenn es aus der Ferne nicht so aussieht, schneit es.","sz":9.5,"box":[53.9,286.8,282.2,383.8],"p":73,"i":4,"sec":"die-anstalt"},{"t":"p","x":"Diese Gebäude kann der Schauplatz für viele verschiedene Szenen sein: Das Team könnte Nachforschungen anstellen, Therapeut:innen von Heilung für die Gebrochenen festnehmen, einen Überfall verüben, jemanden befreien oder Beweise suchen. Sie könnten auch als eingesperrte Patienten aufwachen.","sz":9.5,"box":[53.9,392.5,284.7,464.5],"p":73,"i":5,"sec":"die-anstalt"},{"t":"sh","x":"<b>DIE ANKUNFT IN DER ANSTALT</b>","sz":10.0,"box":[54.3,478.1,224.6,488.1],"p":73,"i":6,"sec":"die-anstalt"},{"t":"p","x":"Du kannst eine Atmosphäre des Schreckens schaffen, indem du das Team auf dem Weg zur Anstalt mit dem Auto (oder einem anderen Transportmittel) verunglücken oder fast verunglücken lässt. Beschreibe, wie das Fahrzeug auf <i>Glatteis</i> oder einer <i>nassen Straße</i> in Richtung einer hohen, kräftigen Tanne rutscht. Die Fahrer:in oder andere SC können <b>Ein Risiko eingehen</b>, um einen Unfall zu vermeiden. Wenn das Auto verunglückt, sind Eissplitter und Blut im Schnee ein großartiges Bildmotiv. Die Ankunft der SC in der Anstalt beginnt mit einem Hauch von Bedrohung.","sz":9.5,"box":[53.9,493.6,279.0,628.1],"p":73,"i":7,"sec":"die-anstalt"},{"t":"sh","x":"<b>DAS UMFELD</b>","sz":10.0,"box":[54.3,641.8,124.5,651.8],"p":73,"i":8,"sec":"die-anstalt"},{"t":"p","x":"Die Anstalt, die für die Unterbringung „krimineller Geisteskranker“ gedacht ist, ist praktisch ein Gefängnis. Sie ist von einer hohen Backsteinmauer mit <i>Stacheldraht</i> umgeben, mit einem schmiedeeisernen Tor an der Vorderseite und einer kleinen verschlossenen Tür hinten zum Wald. An der Mauer sind Sicherheitskameras angebracht. Dahinter erstreckt sich ein karger Hof mit welkem Gras, bedeckt mit Frost und Schnee.","sz":9.5,"box":[53.9,657.3,278.4,766.8],"p":73,"i":9,"sec":"die-anstalt"},{"t":"p","x":"Alle Eingänge sind mit <i>Schiebetüren</i> (Doppeltürschleusen) und Kameras ausgestattet. Sie müssen aus der Ferne vom Wachraum geöffnet werden. Ein gewaltsames Öffnen löst Alarm aus, aber sonst sind die Sicherheitssysteme veraltet. Die SC könnten alles mit Hilfe von <b>Nachforschungen</b>, <b>Heimlichkeit</b> und <b>Ein Risiko eingehen</b> überwinden. Auf dem Hof patrouillieren keine Wachleute, aber drinnen schon (verwende die Bedrohung Psychiatriepfleger:innen, S. 70, sowohl für Pfleger:innen als auch für Wachleute).","sz":9.5,"box":[309.0,59.9,538.8,181.9],"p":73,"i":10,"sec":"die-anstalt"},{"t":"sh","x":"<b>DER GRUNDRISS</b>","sz":10.0,"box":[309.4,195.5,399.2,205.5],"p":73,"i":11,"sec":"die-anstalt"},{"t":"p","x":"Die Anstalt ist U-förmig, mit einem kleineren Hauptgebäude in der Mitte und zwei Seitenflügeln mit den einzelnen Stationen.","sz":9.5,"box":[309.0,211.1,532.3,245.6],"p":73,"i":12,"sec":"die-anstalt"},{"t":"p","x":"Im <b>Hauptgebäude</b> befinden sich der Empfang, die Verwaltung, die Schlafräume der Wachen und ihr <b>Aufenthaltsraum</b>. Das Wachpersonal ist für die Umgebung zuständig und kümmert sich um die Patient:innen nur, falls jemand zu fliehen versucht.","sz":9.5,"box":[309.0,254.3,540.9,313.8],"p":73,"i":13,"sec":"die-anstalt"},{"t":"p","x":"Der <b>Südflügel</b> beherbergt die meisten der armen Patient:innen, die diesen Ort ihr Zuhause nennen. Viele von ihnen sind weit davon entfernt, kriminell zu sein, und leiden an schlimmeren psychischen Erkrankungen als bei ihrer Ankunft. Sie sind in ehemals weißen und hübschen Zimmern untergebracht, die nicht wie die Gefängniszellen aussehen, die sie eigentlich sind. Türschlösser werden elektronisch vom <b>Schwesternzimmer</b> aus gesteuert. Die Bewegungsfreiheit auf dieser Station ist weniger eingeschränkt als anderswo, aber es gibt überall <t>aufmerksame 1</t> Pfleger:innen.","sz":9.5,"box":[309.0,322.4,541.4,456.9],"p":73,"i":14,"sec":"die-anstalt"},{"t":"p","x":"Im <b>Nordflügel</b> befindet sich die Krankenstation, in der therapeutische Tests stattfinden und in deren Keller die problematischsten Fälle in Einzelhaft darben. Hier sind die Sitzungsräume für die Aktivitäten von Heilung für die Gebrochenen. Das mittlere Stockwerk dieses Flügels ist der <u>„Spezialabteilung“</u> gewidmet, in der die Direktorin der Einrichtung, Dr. Esther Monahan (alias Dr. Krystal Knight), üblicherweise arbeitet.","sz":9.5,"box":[309.0,465.6,541.3,562.6],"p":73,"i":15,"sec":"die-anstalt"},{"t":"sh","x":"<b>DIE PATIENT:INNEN, DAS PERSONAL UND DR. MONAHAN</b>","sz":10.0,"box":[309.4,576.2,536.0,598.2],"p":73,"i":16,"sec":"die-anstalt"},{"t":"p","x":"Die Anstalt ist mit einer Empfangsdame, Wachen, Pfleger:innen und den Psychiater:innen und Psycholog:innen von Heilung für die Gebrochenen besetzt. Wer in der Anstalt arbeitet oder dort einsitzt weiß, dass <b>Dr. Esther Monahan</b> Direktorin und leitende Psychiaterin des Instituts ist. <b>Nachforschungen</b> zeigen, dass Angestellte <t>Todesangst 3</t> haben (was es schwierig macht Informationen zu erhalten). Bittet man, Monahan zu identifizieren, erhält man widersprüchliche Aussagen:","sz":9.5,"box":[309.0,603.8,540.6,713.3],"p":73,"i":17,"sec":"die-anstalt"}],"size":[595.276,841.89]},"74":{"tab":"","blocks":[{"t":"p","x":"• Einige haben sie noch nie gesehen.","sz":9.5,"box":[53.9,59.9,209.8,69.4],"p":74,"i":0,"sec":"die-anstalt"},{"t":"p","x":"• Einige neue Mitarbeiter:innen oder Patient:innen, die Dr. Knight gesehen haben, glauben, dass sie Dr. Monahan ist. Sie kennen ihr Alter nicht, schätzen sie aber auf Ende 40.","sz":9.5,"box":[53.9,78.1,284.6,125.1],"p":74,"i":1,"sec":"die-anstalt"},{"t":"p","x":"• Andere, die dort schon länger arbeiten oder leben, aber Dr. Knight noch nie gesehen haben, vermuten, dass Dr. Monahan sehr alt, fast hundert Jahre, sein und aussehen muss (so wie die echte Dr. Monahan heute aussähe) Sie arbeitet dennoch weiter.","sz":9.5,"box":[53.9,133.8,278.6,193.3],"p":74,"i":2,"sec":"die-anstalt"},{"t":"p","x":"• Wer die ganze Geschichte kennt (vor allem leitende Mitglieder von Heilung für die Gebrochenen), bezeichnen Krystal Knight als Dr. Monahan, um die Sache und ihre Taten zu vertuschen.","sz":9.5,"box":[53.9,201.9,278.3,248.9],"p":74,"i":3,"sec":"die-anstalt"},{"t":"p","x":"• Eine alte Patientin, die an Wahnvorstellungen leidet, sagt zwar die Wahrheit, schmückt die Geschichte aber so aus, dass sie unglaubwürdig wird (<i>Ich glaube, sie ist eine Zeitreisende!</i>).","sz":9.5,"box":[53.9,257.6,285.3,304.6],"p":74,"i":4,"sec":"die-anstalt"},{"t":"card","x":"<b>Dr. Monahan verbringt die meiste Zeit</b> in der <u>Spezialabteilung</u> im dritten Stock des Nordflügels. Niemand sie sie je kommen oder gehen.","sz":null,"k":"yellow","box":[54.1,316.2,286.6,362.6],"p":74,"i":5,"sec":"die-anstalt"},{"t":"sh","x":"<b>EINZELHAFT</b>","sz":10.0,"box":[309.4,62.8,379.5,72.8],"p":74,"i":6,"sec":"die-anstalt"},{"t":"p","x":"<b>Dr. Knight hat keinen Spaß daran ihre Feinde einfach zu töten. Sie infiziert sie mit Selbst- oder Riss- Hass und schaut zu, wie viel Schaden sie anrichten.</b> Wenn SC oder NSC in der Anstalt landen, wachen sie im Keller des Nordflügels in separaten, benachbarten Gummizellen auf, in denen die Temperatur leicht unter dem Gefrierpunkt liegt (jede Stunde, die sie ab dem Aufwachen dort bleiben, bringt <t>erfrierend 1</t>). Besonders schwierige Patienten tragen eine Zwangsjacke (<t>gefesselt 3</t>), während die sedierten sich <t>benommen 1</t> fühlen oder <t>Kopfschmerzen 1</t> haben. Außerdem sind alle <t>rechtlos 5</t>. Sie können einander weder sehen noch hören, es sei denn, jemand öffnet die Tür von außen. Die Zellen haben <i>Stahltüren</i>, die mit <i>spiegelndem Eis</i> bedeckt sind, das Magie und Energie reflektiert.","sz":9.5,"box":[309.0,78.5,541.8,262.8],"p":74,"i":7,"sec":"die-anstalt"},{"t":"card","x":"<b>Die Tür zur letzten Zelle des Blocks ist eingefroren und von einem Eisblock umschlossen.</b> Darin findet man den gefrorenen und verstümmelten Leichnam der echten Dr. Monahan. Die gerichtsmedizinische Analyse wird zeigen, dass sie seit Jahren tot ist.","sz":null,"k":"yellow","box":[309.3,276.8,541.7,360.6],"p":74,"i":8,"sec":"die-anstalt"}],"size":[595.276,841.89]},"75":{"tab":"","blocks":[],"size":[595.276,841.89]},"76":{"tab":"","blocks":[{"t":"h","x":"DIE ALTE „NUR-EINE-GEFANGENE„-MASCHE","sz":14.0,"box":[65.2,70.9,268.6,84.9],"p":76,"i":0,"sec":"die-anstalt"},{"t":"p","x":"Krystal Knight könnte versuchen, das Team zu täuschen, indem sie vorgibt, eine misshandelte Patientin zu sein (das sollte nicht schwer fallen, sie war viele Jahre lang eine). Sie schließt sich in einer Zelle ein und lässt die Jalousie offen, damit das Team sie weinen hören kann. Sie bittet, befreit zu werden und gibt vor, eine Verbündete oder Führerin zu sein. Sie nennt ihnen ihren echten Namen und könnte als Teil der Tarngeschichte versehentlich einige echte Informationen über ihre Vergangenheit preisgeben.","sz":9.0,"box":[65.2,97.4,272.0,214.4],"p":76,"i":1,"sec":"die-anstalt"},{"t":"p","x":"Krystal Knight versucht die SC dazu zu bringen, sich zu öffnen und ihre Traumata, Ängste und ihre Wut zu offenbaren, damit sie sie später gegen sie verwenden kann. Je mehr Zeit das Team mit ihr verbringt, desto arglistiger dringt sie in die Gedanken der SC ein. Für jede Szene oder Drehpause in ihrer Gegenwart wählt sie einen anwesenden SC aus und aktiviert die Spezialaktion <b>Dunkle Gedanken</b> gegen ihn (s. S. Therapeut:in von Heilung für die Gebrochenen, S. 68).","sz":9.0,"box":[65.2,223.1,274.4,340.1],"p":76,"i":2,"sec":"die-anstalt"},{"t":"sh","x":"<b>DIE PATIENT:INNENAKTEN</b>","sz":10.0,"box":[54.3,364.7,202.4,374.7],"p":76,"i":3,"sec":"die-anstalt"},{"t":"p","x":"Beim Zugriff auf die Ablage der Anstalt, sei es ein Aktenschrank oder eine Festplatte, findet man die Patient:innenakten.","sz":9.5,"box":[53.9,380.2,264.4,414.7],"p":76,"i":4,"sec":"die-anstalt"},{"t":"card","x":"<b>Jedes Opfer („Patient:in“) von Heilung für die Gebrochenen ist hier verzeichnet</b>, darunter Martha Ellis (<i>Der sanfte Tod</i>), Maximilian Drake (<i>Kirmes der Maschinen</i>), Felicia Pema Jones, Ruben Stone und jeder andere Charakter, SC oder NSC, der mit der Organisation in Kontakt kam. Die Akten enthalten eine Analyse des Lebens, Mythos und Fähigkeiten des Risses.","sz":null,"k":"yellow","box":[54.1,425.4,286.6,534.2],"p":76,"i":5,"sec":"die-anstalt"},{"t":"card","x":"<b>Dr. Knights Akte ist auch hier, aber tief vergraben.</b> Sie enthält ein Foto der Frau, die viele heute als Dr. Esther Monahan kennen. Der Akte zufolge hat Dr. Monahan Dr. Knight vor etwa 80 Jahren eingewiesen, nachdem sie einen „Nervenzusammenbruch“ hatte. Die Akte ist voll von Berichten über Zwangsbehandlungen, denen man sie unterzogen hat, darunter experimentelle Psychopharmaka, Schocktherapie und eine misslungene Lobotomie.","sz":null,"k":"yellow","box":[54.1,543.5,286.6,677.4],"p":76,"i":6,"sec":"die-anstalt"},{"t":"card","x":"Die Akte enthält ein Dokument, aus dem hervorgeht, <b>dass sie Eignerin von <u>Aurora Glas,</u> einer Glasfabrik, war und ist</b>.","sz":null,"k":"yellow","box":[54.1,686.6,286.6,733.0],"p":76,"i":7,"sec":"die-anstalt"},{"t":"h","x":"DIE HISTORISCHE GESELLSCHAFT","sz":16.0,"box":[333.9,68.9,451.1,101.9],"p":76,"i":8,"skip":true,"sec":"die-historische-gesellschaft"},{"t":"ro","x":"Graham, im altertümlichen Anzug mit Monokel, schaut euch von seinem schweren Eichen-Empfangstresen aus an und begrüßt euch in der Historischen Gesellschaft der Stadt. Ihr seht euch um: Es wirkt wie ein Labyrinth aus Bibliotheksregalen, gefüllt mit klassischen dunklen Holzmöbeln mit roten Polstern. Es riecht nach alten Büchern und Mottenkugeln. Das Seltsame ist, dass außer Graham niemand hier ist.","sz":9.0,"box":[317.5,104.3,538.9,210.5],"p":76,"i":9,"sec":"die-historische-gesellschaft"},{"t":"p","x":"Die Historische Gesellschaft der Stadt residiert in einem antiken Gebäude in einer der unbekannteren, mit Kopfsteinpflaster versehenen Seitenstraße der Altstadt. Mit Büchern, Mikrofilmen und Zeitungsarchiven verfügt sie über umfangreiche Informationen der letzten Jahrhunderte der Stadt. Alles davor gleitet in den Bereich des Mythos ab, und obwohl es Texte aus dieser Zeit gibt, werden sie ungenauer und seltsamer, je weiter sie zurückreichen. Das Team kann hier zu jedem Zeitpunkt der Ermittlungen nach Hinweisen auf Dr. Monahan, Dr. Knight oder jemand anderen suchen.","sz":9.5,"box":[309.0,219.5,540.1,354.0],"p":76,"i":10,"sec":"die-historische-gesellschaft"},{"t":"p","x":"<b>Die Historische Gesellschaft ist eine Falle der Torwächter:innen für neugierige Risse.</b> Schläfer:innen interessieren sich nicht für die tatsächliche Vergangenheit. Sie halten sich an die Version, die ihnen passt. Sogar Historiker:innen der Schläfer:innen arbeiten mit erfundenen Berichten, die der Nebel ausgeheckt hat. Jemand, der die Wahrheit herausfinden will, kann nur ein Riss sein, und zwar ein gefährlicher. Die Torwächter:innen würden gerne alle Informationen löschen. Ihre oberste Direktive ist es aber, Risse zu fangen, und dafür brauchen sie eine Sammlung wahren Wissens, mit der sie sie anlocken können (Sie haben es ohne Erfolg mit gefälschtem Wissen als Köder versucht. Das Schicksal hat einfach keinen Riss dorthin geführt).","sz":9.5,"box":[309.0,362.8,540.4,534.6],"p":76,"i":11,"sec":"die-historische-gesellschaft"},{"t":"p","x":"<b>Graham</b> (nicht sein richtiger Name), der Vertreter der Historischen Gesellschaft und Rezeptionist im Anzug, ist in Wirklichkeit der Wachposten der Torwächter:innen. Er soll feststellen, ob es sich bei den Besucher:innen um Schläfer:innen oder Risse handelt und im letzteren Fall einen Trupp rufen, der sie neutralisiert. Es fragt sich nur, wer wen zuerst identifiziert. Sobald ein Hinweis für eine zu tief gehende Frage ausgegeben wird, ist es Zeit für eine Benebelung.","sz":9.5,"box":[309.0,543.3,538.4,652.8],"p":76,"i":12,"sec":"die-historische-gesellschaft"},{"t":"p","x":"Unabhängig davon, ob das Team mit den Torwächter:innen kämpft oder nicht, wird deren Oberkommando bei einem Durchsickern von Informationen an das Team die Bemühungen zur Bewachung der Historischen Gesellschaft vervierfachen, so dass außer bei einem epischen Einbruch nichts mehr zu finden ist.","sz":9.5,"box":[309.0,661.5,535.3,733.5],"p":76,"i":13,"sec":"die-historische-gesellschaft"}],"size":[595.276,841.89]},"77":{"tab":"","blocks":[{"t":"h","x":"GRAHAM, DER HILFSBOT","sz":14.0,"box":[65.2,72.3,179.7,86.3],"p":77,"i":0,"sec":"die-historische-gesellschaft"},{"t":"p","x":"Wenn ihr im Neon Noir (80er Jahre) oder in einer düsteren Gegenwart spielen, könnte das Team virtuell auf die Datenbank der Historischen Gesellschaft zugreifen. Dann ist Graham ein Bot oder virtueller Assistent, der aktiv wird, wenn sich ein SC im Datenbanksystem anmeldet. Alle seine Fähigkeiten gelten auch online, und er kann als harte Aktion jede Maskierungssoftware zum Absturz bringen, die Hacker:innen einsetzen (<t>enttarnt 3</t>). Die alarmierte Spezialeinheit taucht am physischen Standort auf.","sz":9.0,"box":[65.2,98.8,272.0,215.8],"p":77,"i":1,"sec":"die-historische-gesellschaft"},{"t":"sh","x":"<b>SACHDIENLICHE INFORMATIONEN</b>","sz":10.0,"box":[54.3,254.8,244.4,264.8],"p":77,"i":2,"sec":"die-historische-gesellschaft"},{"t":"card","x":"<b>Den Aufzeichnungen nach ist Dr. Monahan 102 Jahre alt.</b> Nur eine weitere Person in ihrem Umfeld ist so alt: eine Patientin namens <b>Krystal Knight</b>. Für keine gibt es eine Sterbeurkunde oder Hinweise auf Manipulationen.","sz":null,"k":"yellow","box":[54.1,278.2,286.6,349.3],"p":77,"i":3,"sec":"die-historische-gesellschaft"},{"t":"card","x":"Zeitungen aus den Anfangsjahren der Stadt zeigen, <b>dass Dr. Krystal Knight vor ihrer Einweisung eine erfolgreiche Psychiaterin für die Reichen und Schönen war</b>, die dabei die sozialen Probleme der Stadt beheben wollte.","sz":null,"k":"yellow","box":[54.1,358.6,286.6,430.0],"p":77,"i":4,"sec":"die-historische-gesellschaft"},{"t":"card","x":"Dr. Knights Karriere endete, als sie einen „Nervenzusammenbruch“ erlitt und in die Anstalt kam. Seitdem hat die Welt nichts mehr von ihr gehört. Ein Zeitungsfoto von ihrem Badezimmer am Tag ihrer Einweisung zeigt einen <b>zerbrochenen Spiegel auf dem Boden</b>.","sz":null,"k":"yellow","box":[54.1,439.2,286.6,523.0],"p":77,"i":5,"sec":"die-historische-gesellschaft"},{"t":"p","x":"<b>Knight war und ist Haupeignerin von</b> <u>Aurora Glas,</u> einer Glasfabrik. Aus den Finanzunterlagen geht hervor, dass sie ihre Anteile als „Entgelt für geleistete Dienste“ von <b>Corbin Payne</b>, dem legendären Baulöwen der Stadt, erhielt.","sz":10.0,"box":[62.4,537.7,273.6,597.7],"p":77,"i":6,"sec":"die-historische-gesellschaft"},{"t":"p","x":"Wenn du <i>Parzival</i> als übergreifenden Fall nutzt und das Team ihn bereits begonnen hat, findet es hier vielleicht Hinweis, die zu dem Akt passen, in dem sie sich gerade befinden, insbesondere Zeitungsausschnitte über Corbin Payne.","sz":10.0,"box":[62.4,618.2,275.9,678.2],"p":77,"i":7,"sec":"die-historische-gesellschaft"},{"t":"h","x":"GRAHAM (WACHPOSTEN DER","sz":12.0,"box":[317.5,61.6,462.6,73.6],"p":77,"i":8,"sec":"die-historische-gesellschaft"},{"t":"threat","stars":"★★★","name":"TORWÄCHTER:INNEN)","spectra":"VERLETZEN ODER UNSCHÄDLICH MACHEN 4","items":["<b>Wachposten</b>: Einmal pro Szene, wenn das Team zum ersten Mal Graham zu <b>Überzeugen</b> oder <b>Heimlichkeit</b> versucht, gib ihm <t>aufmerksam 2</t>.","<b>Schutzzeichen der Offenbarung</b>: Wenn das Team versucht, illusorische, irreführende oder bewusstseinsverändernde Mythos-Kräfte in Grahams Nähe einzusetzen, verpuffen sie. SC können solche Stärken nicht nutzen, bestehende Effekte erlöschen.","<b>Unheimliches Gefühl</b>: Bei <b>Nachforschungen</b>, um mehr über Graham zu erfahren, hat man das Gefühl, dass er undurchschaubar ist. Graham hat dann <t>mysteriös 2</t>. Der Zustand kann Stufe 4 nicht überschreiten.","<b>Schutzzeichen der Verhüllung</b>: Einmal pro Szene nimmt jeder in Grahams Umgebung <t>vergesslich 5</t>. Es steht ihm dann frei zu fliehen.","<b>Verhüllung</b>: Einmal pro Szene verbrennt die SL, wenn jemand mit Mythos-Kräften angreifen will, zuerst zwei Stärken, die dabei zum Einsatz kamen.","Seine Wachsamkeit wiedererlangen (sich selbst <t>aufmerksam 2</t> geben)","Eine Torwächter:innen-Spezialeinheit herbeirufen (erstelle eine neue Bedrohung)","Jemanden benebeln (<t>vage Erinnerungen 3</t> oder zwei Mythos-Stärken verbrennen)","Eine Standard-Pistole abfeuern (<t>Schusswunde 3</t>) oder einfache Kampfsportarten anwenden (<t>niederhalten 2</t> oder <t>Prellung 2</t>)","Ironisch lächeln, wenn jemand versucht, ihn mit Mythos-Kräften zu täuschen, und scheitert","Manschetten aufknöpfen und die Ärmel hochkrempeln, um Torwächter-Tätowierungen zu enthüllen."],"box":[430.8,75.5,461.4,87.5],"p":77,"i":9,"sec":"die-historische-gesellschaft"}],"size":[595.276,841.89]},"78":{"tab":"","blocks":[{"t":"h","x":"TORWÄCHTER:INNEN-SPEZIALEINHEITEN","sz":12.0,"box":[62.4,61.6,266.7,73.6],"p":78,"i":0,"sec":"die-historische-gesellschaft"},{"t":"p","x":"★★★★","sz":12.0,"box":[62.4,75.5,103.2,87.5],"p":78,"i":1,"sec":"die-historische-gesellschaft"},{"t":"p","x":"Die Torwächter:innen-Spezialagent:innen sind die furchterregendste Bedrohung, der ein Riss begegnen kann. Von Kopf bis Fuß in Anti-Mythos-Ausrüstung gekleidet und von den Besten ausgebildet, verspeisen sie Risse zum Frühstück, Mittag- und Abendessen.","sz":9.0,"box":[62.4,98.6,275.4,155.6],"p":78,"i":2,"sec":"die-historische-gesellschaft"},{"t":"p","x":"Die Trenchcoats, Jacken oder Westen der Spezialeinheiten schützen sie vor den meisten Mythos-Kräften. Nur die stärksten Mythos-Angriffe können das intensive Nebelfeld, das die Rüstung erzeugt, unschädlich machen, und das nur kurzzeitig (es sei denn, ein SC kann einen permanenten <t>Überladungs</t>-Zustand erzeugen). Anstatt einzelne zu benebeln, hat jedes Team meist einen tragbaren Nebelstrahl dabei, um kontinuierlich die Erinnerungen aller in der Nähe auszulöschen. Ihre mächtigen Versiegelungs-Schutzzeichen können besiegte Ziele in Zukunft in Schach halten. Mit gebündelten Kräften können sie Risse dauerhaft versiegeln und in Schläfer:innen verwandeln.","sz":9.0,"box":[62.4,164.6,277.7,317.6],"p":78,"i":3,"sec":"die-historische-gesellschaft"},{"t":"sh","x":"<b>VERLETZEN ODER UNSCHÄDLICH MACHEN 4 / ÜBER- LADEN 6</b>","sz":12.0,"box":[62.4,328.1,275.9,352.1],"p":78,"i":4,"sec":"die-historische-gesellschaft"},{"t":"p","x":"• <b>Kollektiv</b>: Dieses Kollektiv hat einige Mitglieder und einen Größenfaktor von 1. • <b>Einsatz</b>: Wenn eine Spezialeinheit den Schauplatz betritt, gib ihr <t>taktische Deckung 2</t>. • <b>Mythosfeste Kleidung</b>: » <b>Passiv</b>: Wenn sie einen von einer Mythoskraft auferlegten Zustand nimmt, wird er zu <t>überladen</t>. » <b>Aktiv</b>: Eine Agent:in kann einen <t>Überladungs</t>- Zustand beliebiger Stufe nehmen, um jemandem, der Mythoskräfte gegen sie aktiviert, einen <t>Benebelungs</t>-Zustand derselben Stufe zu verleihen. » <b>Wiederaufladen</b>: Als weiche Aktion (nach einer Spieler:innen-Aktion) entfernt eine Agent:in alle nicht dauerhaften Überlastungszustände. » <b>Überladen</b>: Wenn <i>Überladung 6</i> erreicht ist, versagen die <b>passive</b> und <b>aktive</b> Verteidigung des Mantels, und er ist nutzlos. Nach der nächsten Spieler:innen-Aktion verliert er alle nicht permanenten <t>Überladungs</t>-Zustände. • <b>Nahkampfexpert:in</b>: Nahkampf beginnt die Spezialagent:in mit einer harten Aktion. • <b>Militärische Disziplin</b>: Wenn eine Torwächter:innen-Spezialagent:in einen sozialen oder emotionalen Zustand nimmt, reduziert sich seine Stufe um 2.","sz":9.0,"box":[62.4,356.6,277.7,653.6],"p":78,"i":5,"sec":"die-historische-gesellschaft"},{"t":"p","x":"• Einen Hagel von Anti-Mythos-Energiebolzen abfeuern (<t>versiegelt 4</t>) • Standardmunition mit Nebelverankerung abfeuern, um zu verletzen oder zu töten (<t>Schusswunde 3</t> und <t>versiegelt 3</t>) • Kampftraining zum Fesseln oder Verletzen nutzen (<t>gefesselt 3</t> oder <t>Armbruch 3</t>) oder ein Schutzzei-","sz":9.0,"box":[62.4,662.6,276.3,743.6],"p":78,"i":6,"sec":"die-historische-gesellschaft"},{"t":"p","x":"chen des Vergessens auflegen (<t>vage Erinnerungen 3</t>) • Einem entmachteten oder besiegten Riss ein Nebelsiegel verpassen (<t>versiegelt 5</t>) • Neu formieren (entfernt bis zu 2 Stufen negativer taktischer Zustände von sich oder Verbündeten und verleiht der Einheit einen Vorteil der Stufe 2) • Den Nebelstrahl aktivieren (<t>Dichter Nebel 1</t> in der Umgebung. Verleiht allen Schläfer:innen und entmachteten Rissen <t>vage Details 1</t>) • Rückzug in den Nebel (<b>Ihnen etwas verweigern, das sie wollen</b>)","sz":9.0,"box":[317.5,62.3,532.9,191.4],"p":78,"i":7,"sec":"die-historische-gesellschaft"},{"t":"p","x":"• Aus einer Nebelschwade heraus angreifen • Mit den Fingern ein leuchtendes magisches Schutzzeichen zeichnen • Ein runenbedecktes Sturmgewehr oder eine solche Schrotflinte anlegen","sz":9.0,"box":[317.5,200.3,532.5,257.3],"p":78,"i":8,"sec":"die-historische-gesellschaft"}],"size":[595.276,841.89]},"79":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 3:","sz":14.0,"box":[53.9,61.9,122.0,75.9],"p":79,"i":0,"skip":true,"sec":"schicht-3-steine-im-glashaus"},{"t":"h","x":"STEINE IM GLASHAUS","sz":23.0,"box":[53.9,84.2,260.6,107.2],"p":79,"i":1,"skip":true},{"t":"h","x":"AURORA GLAS","sz":16.0,"box":[79.7,120.8,172.0,136.8],"p":79,"i":2,"skip":true,"sec":"aurora-glas"},{"t":"p","x":"Aurora Glas ist das Bindeglied zwischen der Anstalt und Dr. Knights großem Plan: die dunkle Magie zu nutzen, die sie in die Fenster der Stadt gebunden hat, um diese in einen emotionalen Winter zu hüllen. Man kann über das Unternehmen nachforschen: online, im Gewerbeamt der Stadt, bei der Firma selbst, in den Wohnungen ihrer Mitarbeiter usw.","sz":9.5,"box":[53.9,140.7,281.1,225.2],"p":79,"i":3,"sec":"aurora-glas"},{"t":"card","x":"Aurora Glas ist der einzige Hersteller von Bauglas in der Stadt – die Firma stellt alle Fensterscheiben in der Stadt her.","sz":null,"k":"yellow","box":[54.1,236.2,286.6,282.5],"p":79,"i":4,"sec":"aurora-glas"},{"t":"card","x":"<b>Der offizielle Standpunkt der Firma zu ihrer Hauptaktionärin, Dr. Krystal Knight, ist, dass man davon ausgeht, sie sei vor Jahrzehnten in der Anstalt gestorben.</b> Sie begründen die fehlende Sterbeurkunde mit Inkompetenz des dortigen Personals, mangelnde Dokumentation und möglicherweise Korruption. Es gibt einen langen Rechtsstreit, aber da die meisten Führungskräfte in einem Interessenkonflikt stehen, fehlt bisher ein Urteil.","sz":null,"k":"yellow","box":[54.1,291.7,286.6,425.7],"p":79,"i":5,"sec":"aurora-glas"},{"t":"card","x":"<b>Wenn jemand das Unternehmen jenseits des Nebels untersucht,</b> kann er in jeder Fensterscheibe Spuren des Teufelsspiegels finden. Weitere Nachforschungen können die Spuren in jeder Glasscheibe der Stadt aufdecken.","sz":null,"k":"yellow","box":[54.1,434.9,286.6,506.0],"p":79,"i":6,"sec":"aurora-glas"},{"t":"card","x":"<b>Ein pensionierter, hochrangiger Mitarbeiter</b> der Firma kann sich vage an den Tag erinnern, an dem die Scherben von Krystal Knights Spiegel zum Einschmelzen in die Fabrik kamen. Er entsinnt sich, dass die Lage angespannt war und die Mitarbeiter:innen grundlos Streit anfingen und dabei Glas zerbrachen (er hat immer noch eine Narbe davon). Es folgte eine Kündigungswelle, Arbeitnehmer:innen ließen sich von ihren Partner:innen scheiden, wurden gewalttätig oder nahmen sich das Leben.","sz":null,"k":"yellow","box":[54.1,515.2,286.6,661.5],"p":79,"i":7,"sec":"aurora-glas"},{"t":"card","x":"Daraus lässt sich ableiten, <b>dass Knight durch das Glas eine Art Magie besitzt, die sie aktivieren will</b>. Ein Ingenieur könnte die Theorie aufstellen, dass sie dies mit massiven Schockoder Schallwellen tun könnte.","sz":null,"k":"yellow","box":[309.3,54.1,541.7,125.6],"p":79,"i":8,"sec":"aurora-glas"},{"t":"p","x":"Der pensionierte Manager oder alte Akten könnten auf die ursprüngliche Fabrik hinweisen, die heute verlassen ist. Wenn die SC den Ort untersuchen, bemerken sie zwielichtige Machenschaften in der Umgebung. Der Ort selbst ist leer, abgesehen von einem alten Ofen (s. S. <u>Alte Aurora-Glashütte,</u> <i>Athanor</i>).","sz":10.0,"box":[317.5,140.2,530.2,225.3],"p":79,"i":9,"sec":"aurora-glas"},{"t":"h","x":"DIE „SPEZIALABTEILUNG“","sz":16.0,"box":[334.8,253.1,505.3,269.1],"p":79,"i":10,"skip":true,"sec":"die-spezialabteilung"},{"t":"ro","x":"Der verlassene dritte Stock ist ein ganz in Blautönen gehaltenes Bild des ewigen Winters. Alle Fenster sind zerbrochen, die Scherben der kaputten Scheiben liegen unter ihnen aufgestapelt. Der hereinrieselnde Schnee hat Häufchen an den gefrorenen Wänden der Gänge und Räume gebildet. Es herrscht eine seltsame Stille, doch dann hört man das Knirschen von Glas, das unter Füßen zerbricht. Ein grässlich aussehender Patient, der nur mit einem Kittel bekleidet ist, schlendert barfuß vorbei, murmelt vor sich hin und ignoriert euch. Ihr erhaschst einen Blick auf euch selbst in einer Glasscherbe, die bedrohlich aus dem Fensterrahmen ragt, und ihr hasst, was ihr seht.","sz":9.0,"box":[317.5,271.5,538.9,453.3],"p":79,"i":11,"sec":"die-spezialabteilung"},{"t":"p","x":"Die „Spezialabteilung“ ist Dr. Krystal Knights Versteck und ein möglicher Ort für einen Showdown, sei es mit Knight oder zwischen den SC. Es ist ein Ort des Hasses, vor allem des Selbsthasses, der sich darin entlädt, sich oder seinesgleichen zu verletzen.","sz":9.5,"box":[309.0,462.3,541.2,521.8],"p":79,"i":12,"sec":"die-spezialabteilung"},{"t":"p","x":"<b>Die Hauptverteidigungslinie der Station sind die Schneeflocken der Schneekönigin</b>, eine Schar emotional instabiler Patient:innen, die auf der Station verstreut sind und als menschliche Landminen fungieren. Einst waren sie hoffnungsvolle, glückliche Menschen, deren Träume durch den Verrat ihrer Lieben oder die Lebensumstände zerbrochen sind, so dass sie hier landeten (was Knights eigene Reise widerspiegelt). Passe den Größenfaktor und die Zahl der Schneeflocken, die in einer Szene auftreten, der Feuerkraft des Teams an: Ein Flur könnten nur wenige (Größenfaktor 1) oder eine große Menge an Schneeflocken beherbergen (Größenfaktor 2), während der Kampf gegen die gesamte Station einen Blizzard von Schneeflocken bedeuten könnte (Größenfaktor 3).","sz":9.5,"box":[309.0,530.6,541.3,715.0],"p":79,"i":13,"sec":"die-spezialabteilung"},{"t":"p","x":"Wenn das Team den Effekt nicht aktiv vermeidet, löst de Aufenthalt die Spezialaktion <b>Dunkle Gedanken</b> aus (s. S. Bedrohungsprofil der Therapeut:innen von Heilung für die Gebrochenen, S. 68). Während die","sz":9.5,"box":[309.0,723.7,533.6,770.7],"p":79,"i":14,"sec":"die-spezialabteilung"}],"size":[595.276,841.89]},"80":{"tab":"","blocks":[{"t":"p","x":"SC durch die verschneite Umgebung gehen, sehen sie und ihre Verbündeten sich selbst und Nahestehende in Eis und Glas gespiegelt. Diese Bilder zeigen sie als verachtenswert, erbärmlich oder bösartig. Nur das, was Hass erregt, ist zu sehen. Heimliche Zwistigkeiten, verborgene Rivalitäten und alter Groll tauchen in ihren Köpfen auf. <b>Bitte alle Spieler:innen zu beschreiben, was ihre Charaktere sehen und wie es auf sie wirkt.</b>","sz":9.5,"box":[53.9,59.9,286.6,157.1],"p":80,"i":0,"sec":"die-spezialabteilung"},{"t":"p","x":"Als cineastischer Effekt ertönt von überall Dr. Krystal Knights Stimme, hysterisches Lachen oder bösartige Ansprache (auch wenn sie bei ihnen ist und vorgibt, ihre Verbündete zu sein).","sz":9.5,"box":[53.9,165.6,278.1,212.6],"p":80,"i":1,"sec":"die-spezialabteilung"},{"t":"card","x":"<b>Jenseits des Nebels ist dieser Ort von Hass erfüllt.</b> Die Symbolik des Teufelsspiegels ist überall und hat ihren Ursprung dort, wo Krystal Knight steht, zeigt aber auch gefrorene Splitter in den Herzen derer, die ihr Hass bereits zerfrisst. Vage Bilder aus ihrem Leben manifestieren sich: Empfang und Zerschlagen des Spiegels, das Ertrinken in Selbsthass und die quälende Behandlung durch Dr. Monahan.","sz":null,"k":"yellow","box":[54.1,221.5,286.6,342.7],"p":80,"i":2,"sec":"die-spezialabteilung"},{"t":"threat","stars":"★","name":"SCHNEEFLOCKEN +","spectra":"FESSELN, AUSSCHALTEN ODER TÖTEN 2 / ENT- SCHÄRFEN 3","items":["<b>Kollektiv</b>: Diese Bedrohung kann einen Größenfaktor von 0 (eine Schneeflocken) bis 3 (eine ganze Etage voller Schneeflocken) haben. Jede Erhöhung hebt den Bedrohungswert der Schneeflocken um ★.","<b>Aufgeregt</b>: Wenn eine Schneeflocke die Szene betritt, gib ihr <t>neurotisch 3</t>. Dieser Zustand kann Stufe 4 nicht überschreiten.","Schrei (<t>taub 2</t>), der eine Kettenreaktion auslöst und eine Gruppe ruft, die um einen Faktor größer ist (<b>Die Dinge richtig kompliziert machen</b>)","Einen Wutanfall bekommen und angreifen (<t>zurückgedrängt 2</t>, <t>niedergehalten 2</t>), jemanden mit dem Blick einfrieren (<t>eingefroren 2</t>) oder zusammenbrechen (<t>traurig 2</t>, <t>Schuldgefühle 2</t>)","Einen Eindringling bemerken und die Augen aufreißen"],"box":[151.1,375.6,161.3,387.6],"desc":"Schneeflocken sind Dr. Krystal Knights menschliche Minen. Sie stehen einfach nur da oder laufen umher wie Zombies, gefangen in ihren eigenen Gedanken, und ignorieren einander. Wenn ein Eindringling in ihren Raum eindringt, explodieren sie.","p":80,"i":3,"sec":"die-spezialabteilung"},{"t":"sh","x":"<b>KRYSTAL KNIGHTS BEHANDLUNGSRAUM</b>","sz":10.0,"box":[309.4,62.8,533.7,72.8],"p":80,"i":4,"sec":"die-spezialabteilung"},{"t":"p","x":"In der Mitte des dritten Stocks liegt der Raum, in dem Krystal Knight jahrzehntelang den „Behandlungen“ Monahans ausgesetzt war. Hier scheiterte sie in ihren Augen am Leben und der Behandlung von Corbin Payne, immer und immer wieder, wobei sich ihr Schmerz zu einem Selbsthass entwickelte, wie ihn nur der Teufelsspiegel hervorbringen kann.","sz":9.5,"box":[309.0,78.3,538.0,162.8],"p":80,"i":5,"sec":"die-spezialabteilung"},{"t":"p","x":"Wenn nicht anders angegeben, ist Dr. Knight hier, entweder vor sich hinmurmelnt in einer Ecke zusammengerollt oder sie steht energisch in dem unordentlichen Raum und tut, als sei sie Dr. Monahan. Der Raum, ein umgebauter OP, ist komplett gefliest und mit veralteten „therapeutischen“ Geräten ausgestattet, wie z. B. einem Elektroschockgerät und einem Bett mit Fixiergurten. Allerdings sind Geräte und Bett umgestürzt, die Fliesen gesprungen oder fehlen, und der Raum sieht aus, als hätte hier vor vielen Jahren jemand einen Wutanfall gehabt. Einige Blutflecken sind sichtbar, und von der Decke hängen Eiszapfen. Ein großes Beobachtungsfenster an einer Wand ist zerbrochen, was viel Glas und spiegelnde Flächen für visuelle Effekte bietet.","sz":9.5,"box":[309.0,171.5,540.7,343.5],"p":80,"i":6,"sec":"die-spezialabteilung"},{"t":"card","x":"<b>Wenn man das Thema vorsichtig anspricht, enthüllt Dr. Knight möglicherweise ihre Geschichte.</b> Kriminologisches Profiling oder Mythos-Fähigkeiten, die die Vergangenheit aufdecken, können die wichtigsten Details über Krystal, das Zimmer, ihre Bindung daran usw. ans Licht bringen.","sz":null,"k":"yellow","box":[309.3,358.8,541.7,455.3],"p":80,"i":7,"sec":"die-spezialabteilung"},{"t":"p","x":"Wenn du <i>Parzival</i> als übergreifenden Fall nutzt, wird Krystal Hinweise geben, die mit der Rolle als Gralsritterin zusammenhängen.","sz":10.0,"box":[317.5,469.9,532.9,504.9],"p":80,"i":8,"sec":"die-spezialabteilung"},{"t":"sh","x":"<b>DER PLAN DER ÄRZTIN</b>","sz":10.0,"box":[309.4,530.5,435.4,540.5],"p":80,"i":9,"sec":"die-spezialabteilung"},{"t":"card","x":"<b>Wenn Dr. Knight anwesend ist, hält sie das Team merklich hin.</b> Sie will die SC aufhalten, um zu verhindern, dass sie ihren wichtigen Plan durchkreuzen.","sz":null,"k":"yellow","box":[309.3,548.1,541.7,606.8],"p":80,"i":10,"sec":"die-spezialabteilung"},{"t":"card","x":"Ein genauer Blick in den Raum zeigt, <b>dass dies nicht nur der Ort eines vergangenen Traumas ist – es ist ein Labor</b>. Dr. Knight hat hier etwas entwickelt, aber es ist nicht mehr da.","sz":null,"k":"yellow","box":[309.3,616.0,541.7,674.8],"p":80,"i":11,"sec":"die-spezialabteilung"},{"t":"card","x":"Die zertrümmerten Wandfliesen, umgestürzten Geräte und das zerbrochene Fenster sind Beweise dafür, <b>dass in dem Raum ein starker, kugelförmiger Schallknall erzeugt wurde</b>.","sz":null,"k":"yellow","box":[309.3,684.0,541.7,743.0],"p":80,"i":12,"sec":"die-spezialabteilung"}],"size":[595.276,841.89]},"81":{"tab":"","blocks":[{"t":"threat","stars":"★★★★★","name":"KRYSTAL KNIGHT","spectra":"","items":[],"box":[152.2,57.5,203.2,69.5],"p":81,"i":0,"sec":"die-spezialabteilung"},{"t":"p","x":"Krystal Knight sieht aus wie eine Frau Ende 40. Je nach den Umständen ihres Zusammentreffens mit dem Team kann sie eine Patientin in einer Zwangsjacke sein, zerzaust und wahnsinnig, oder eine Therapeutin in einem eleganten Kostüm (Letzteren kann schnell brechen, um Ersteres zu enthüllen). Manchmal ist ihr Blick leer, als hätte sie alle Schmerzen der Welt ertragen. Ein anderes Mal ist er eine Woge eisigen Hasses auf alles und jeden.","sz":9.0,"box":[62.4,80.6,274.5,185.6],"p":81,"i":1,"sec":"die-spezialabteilung"},{"t":"p","x":"<b>Maximaler Bedrohungswert</b>: Als Gralsritterin ist Krystal eine mächtige Gegnerin. Überlege dir, ob du die Spieler ausreichend gewarnt hast, bevor sie ihr gegenübertreten, oder ob du den Schwierigkeitsgrad reduzierst. Das Team könnte Psycholog:innen und Hellseher:innen rekrutieren. Es könnten mehrere Begegnungen, von denen einige für das Team schlecht ausgehen, nötig sein, um die Schurkin zu besiegen.","sz":9.0,"box":[62.4,194.6,275.1,287.6],"p":81,"i":2,"sec":"die-spezialabteilung"},{"t":"p","x":"<b>Zum Hass zwingen</b>: Die Hass-Zustände der Ritterin sind zwingende Effekte. Wenn ein SC einen solchen Zustand erhält, frag seine Spieler:in, was der Charakter tun möchte (vermutlich sich selbst oder andere verletzen). Für jede gegenteilige Aktion zählt der Hass-Zustand negativ. Stufe 5 zwingt zu solchen Handlungen und auf Stufe 6 verzehrt der Hass den SC dauerhaft und verwandelt ihn in einen Bösewicht, oder er ergreift sofort Maßnahmen, um sich umzubringen (nach Wahl der Spieler:in).","sz":9.0,"box":[62.4,296.6,274.7,413.6],"p":81,"i":3,"sec":"die-spezialabteilung"},{"t":"p","x":"Letztlich sollte die Lösung für Krystal Knights Problem erzählerisch sein. Wenn du die Kampagne spielst, weist sie auf Corbin Payne – wenn er die Wunde verursacht hat, kann er sie vielleicht heilen. Wenn man ihn heilt, bedeutet das vielleicht auch Heilung für Krystal Knight usw. Kann das Team sie noch nicht heilen oder vernichten, möchte es sie vielleicht in ihrem Zustand halten.","sz":9.0,"box":[317.5,59.9,531.9,152.9],"p":81,"i":4,"sec":"die-spezialabteilung"},{"t":"sh","x":"<b>ZERSCHMETTERN 6 / BETÄUBEN – / HEILEN –</b>","sz":12.0,"box":[317.5,163.4,500.8,175.4],"p":81,"i":5,"sec":"die-spezialabteilung"},{"t":"p","x":"• <b>Die Nimmer heilende Wunde</b>: Wenn jemand zum ersten Mal in der Serie versucht, Krystal Knight zu heilen, gib ihr <t>Nimmer heilende Wunde 6</t>. • <b>Dämon:innen erwecken</b>: Krystal Knights erinnert SC in ihrer Nähe sie an alles, was sie an sich selbst verabscheuen (<t>Selbsthass 4</t>). • <b>Geistig unangreifbar</b>: Wenn Krystal Knight einen sozialen oder emotionalen Zustand erlangt, reduziert sich seine Stufe um 3. • <b>Scherben aufsammeln</b>: Wenn Krystal Knights <i>Zerschmettern 6</i> den Maximalwert erreicht, zerbricht sie in eine Million Glasscherben. Verleihe ihr <i>Wiedererstehen 4</i>. Sie kann als weiche Aktion <t>wiedererstehen 1</t> einsetzen. Wenn <i>Wiedererstehen 4</i> den Maximalwert erreicht, entferne alle Zustandswerte von <i>Wiedererstehen</i> und <i>Zerschmettern</i>.","sz":9.0,"box":[317.5,179.9,530.2,368.9],"p":81,"i":6,"sec":"die-spezialabteilung"},{"t":"p","x":"• Jemanden mit einem Blick, Wort oder Laut dort berühren, wo es am meisten wehtut (<t>Selbsthass 4</t>) • Jemanden auffordern, einen anderen zu verletzen (einem SC 3 Feindpunkte oder <t>hasserfüllt 3</t> bei einem anderen geben) • Eine psychologische Bemerkung machen, die jemandes mentale Abwehr schwächt oder überlastet, bis sie bricht (verbrenne bis zu 2 relevante Stärken oder reduziere einen solchen Zustand um 2) • Wenn ihr eine Situation reicht oder sie sich bedroht fühlt, lässt sie Blut in den Adern gefrieren (<t>gefroren 5</t>) oder benutzt Glasmanipulation, um jemanden zu zerschneiden (<t>tödlicher Schnitt 5</t>)","sz":9.0,"box":[317.5,377.9,529.8,530.9],"p":81,"i":7,"sec":"die-spezialabteilung"},{"t":"p","x":"<b>Heilung für Krystal Knight</b>: Wie alle gescheiterten Gralsritter:innen trägt Krystal Knight eine tiefe emotionale Wunde, die ihr der Fischerkönig zugefügt hat, die so genannten <b>Nimmer heilende Wunde</b>, repräsentiert durch einen Zustand der Stufe 6. Nur ein Einsatz von <b>Jetzt reicht’s!</b> kann diesen Zustand beeinflussen: Dr. Knight für eine Szene von den Auswirkungen zu befreien erfordert ein unumkehrbares Opfer, die vollständige Heilung einer solchen Wunde ein ultimatives. Optional kann eine <i>Mega!</i>-<b>Das Blatt wenden</b>-Aktion den Zustand der Stufe 6 für die Dauer einer Szene verringern.","sz":9.0,"box":[62.4,422.6,274.3,563.6],"p":81,"i":8,"sec":"die-spezialabteilung"},{"t":"p","x":"• Zwischen Weinen, hysterischem Lachen und einer wütenden Tirade hin und her wechseln","sz":9.0,"box":[317.5,539.9,525.7,560.9],"p":81,"i":9,"sec":"die-spezialabteilung"}],"size":[595.276,841.89]},"82":{"tab":"","blocks":[{"t":"h","x":"SCHICHT 4:","sz":14.0,"box":[53.9,61.9,122.1,75.9],"p":82,"i":0,"skip":true,"sec":"schicht-4-herzschneeschippen"},{"t":"h","x":"HERZSCHNEESCHIPPEN","sz":23.0,"box":[53.9,84.2,279.8,107.2],"p":82,"i":1,"skip":true},{"t":"h","x":"EIN SCHNEESTURM DES HASSES","sz":16.0,"box":[78.0,120.8,235.7,153.8],"p":82,"i":2,"skip":true,"sec":"ein-schneesturm-des-hasses"},{"t":"ro","x":"Der Krankenwagen rast die Straße hinunter und warnt die anderen Fahrer mit heulenden Sirenen, ihm aus dem Weg zu gehen. Ihr verfolgt ihn und beobachtet besorgt, wie das Fahrzeug vor euch eine scharfe Kurve auf den linken Rädern macht, wobei die hinteren Türen aufklappen und eine Krankenschwester zum Vorschein kommt, die einen sirenenähnlichen Apparat trägt. Sofort gebt ihr Gas und rast los, um dem Wagen den Weg abzuschneiden. Was immer dieses Ding ist, ihr müsst verhindern, dass es die Stadt erreicht.","sz":9.0,"box":[62.4,156.2,283.8,294.8],"p":82,"i":3,"sec":"ein-schneesturm-des-hasses"},{"t":"p","x":"Ob durch Knights letzte drastischer Rede oder das richtige Kombinieren der Beweise, früher oder später erfahren die SC, dass Knights Pläne weit über Heilung für die Gebrochenen hinausgehen. Mit Hilfe der magischen Scherben des Teufelsspiegels hat die Ärztin die Saat des Hasses in der ganzen Stadt verstreut, und zwar in den Scheiben, die Aurora Glas im Laufe der Jahre hergestellt hat. Als Nächstes will sie eine „Schallbombe“ zünden, die all die Scheiben zerspringen lässt, die Spiegelkraft weckt und die Stadt mit einem Schnee bedeckt, der nicht nur die Knochen, sondern auch die Herzen gefrieren lässt.","sz":9.5,"box":[53.9,303.8,282.2,450.8],"p":82,"i":4,"sec":"ein-schneesturm-des-hasses"},{"t":"sh","x":"<b>DIE BOMBE</b>","sz":10.0,"box":[54.3,464.4,115.5,474.4],"p":82,"i":5,"sec":"ein-schneesturm-des-hasses"},{"t":"p","x":"Die kürzlich von der Ärztin perfektionierte Schallbombe ist ein Gerät, das einen hohen Ton produziert, der so viel Hass in sich birgt, dass er alle Fenster in der Stadt zerschmettern kann, vorausgesetzt, man zündet ihn nahe am Stadtzentrum. Der Apparat hat die Größe und Form einer altmodischen handbetriebenen Warnsirene. Wenn das Team das herausfindet, verfrachten","sz":9.5,"box":[53.9,480.0,283.7,564.5],"p":82,"i":6,"sec":"ein-schneesturm-des-hasses"},{"t":"threat","stars":"★★★","name":"KRANKENWAGEN MIT SCHALLBOMBE","spectra":"AUS DEM VERKEHR ZIEHEN 5 / ABFANGEN 5 / IN STELLUNG BRINGEN 3","items":["<b>Fahrzeug</b>: Wenn die Krankenpfleger:innen, die den Wagen fahren, aussteigen, erstelle eine neue Bedrohung: Pfleger:innen der Anstalt. Das geschieht automatisch, wenn <i>Aus dem Verkehr</i> ziehen den Maximalwert erreicht, aber sie nehmen dann <t>verletzt 1</t>.","<b>Schallbombe</b>: Wenn <i>In Stellung bringen</i> den Maximalwert erreicht, zünden die Krankenpfleger:innen die Schallbombe.","Sich dem Ziel nähern (<t>näher kommen 1</t>)","Scharf abbiegen und auf dem Bürgersteig fahren, um Verfolger:innen abzuschütteln (entfernt 2 Stufen vom Zustand auf dem Spektrum <i>Abfangen</i>)","Einen Weg durch den Verkehr nehmen (bis zu drei verkehrsbezogene Schwächen/Stufen entfernen)","Einmal pro Szene einen Raketenwerfer auf verfolgende Fahrzeuge abfeuern (<t>in die Luft gejagt 4</t>, Fahrzeuge in der Nähe werden <t>verbeult 2</t>)","Beschleunigen und in Richtung Stadtzentrum rasen"],"box":[504.4,57.5,535.0,69.5],"p":82,"i":7,"sec":"ein-schneesturm-des-hasses"},{"t":"p","x":"Pfleger:innen die Bombe bereits in den Krankenwagen der Anstalt, der dann in Richtung Stadt rast. Wenn man ihn nicht stoppt, wird die Bombe hochgehen, wenn er in Hörweite der Innenstadt kommt.","sz":9.5,"box":[309.0,391.6,538.1,438.6],"p":82,"i":8,"sec":"ein-schneesturm-des-hasses"},{"t":"sh","x":"<b>WENN DIE BOMBE HOCHGEHT</b>","sz":10.0,"box":[309.4,452.2,474.1,462.2],"p":82,"i":9,"sec":"ein-schneesturm-des-hasses"},{"t":"p","x":"Wenn die Krankenpfleger:innen die Schallbombe zünden, erfüllt ein quälender, schriller Schrei die Luft in der Stadt. Jeder, der sich in unmittelbarer Nähe aufhält, ist <t>taub 5</t>. Alle Scheiben entlang der Straße und gläserne Fassaden überall in der Stadt zerspringen in mikroskopisch kleine, schneeflockenförmige Scherben und überziehen die Stadt, verstärkt durch die Magie des Teufelsspiegels, mit einem Sturm aus gläsernem","sz":9.5,"box":[309.0,467.8,537.8,564.8],"p":82,"i":10,"sec":"ein-schneesturm-des-hasses"}],"size":[595.276,841.89]},"83":{"tab":"","blocks":[{"t":"h","x":"EINE ZWEITE BOMBE?","sz":14.0,"box":[65.2,66.6,167.2,80.6],"p":83,"i":0,"sec":"ein-schneesturm-des-hasses"},{"t":"p","x":"Je nach Verlauf der Kampagne und den Erfolgen und Misserfolgen des Teams kann es sinnvoll sein, Dr. Knight eine zweite Bombe (oder Dutzende) an einem anderen Ort in der Stadt anbringen zu lassen. Selbst wenn das Team eine Bombe entschärft, muss es noch mehr tun, um die ganze Stadt zu retten.","sz":9.0,"box":[65.2,93.2,275.0,162.2],"p":83,"i":1,"sec":"ein-schneesturm-des-hasses"},{"t":"p","x":"Schnee. Dieser Teufelsschnee ist eiskalt, aber da er aus Glas besteht, schmilzt er nicht (es sei denn, man setzt ihn der extremen Hitze aus, die zum Schmelzen von Glas erforderlich ist). Ein Kontakt mit damit oder das Spüren der Kälte, die er verursacht, verwirrt die Wahrnehmung der Menschen, so dass sie nur noch das Negative und Hässliche um sich herum sehen. Davon sind alle Menschen in der Stadt betroffen, nicht nur Risse.","sz":9.5,"box":[53.9,187.5,285.5,284.5],"p":83,"i":2,"sec":"ein-schneesturm-des-hasses"},{"t":"p","x":"Wie sich dies auf die Stadt auswirkt, bleibt dir überlassen. Zwei Optionen wären:","sz":9.5,"box":[53.9,293.2,283.3,315.2],"p":83,"i":3,"sec":"ein-schneesturm-des-hasses"},{"t":"p","x":"• <b>Der harte Winter des Herzens</b>: Der Schneesturm hat eine anhaltende Wirkung auf die Stadt, die auch in den nächsten Fällen, die ihr spielt, anhält. Die Stadtbewohner werden bösartiger, argwöhnischer und negativer, was es schwer macht, Geschäfte zu tätigen und Beziehungen zu pflegen. Die Mord- und Selbstmordrate steigt. Die Stadt erleidet <t>Schneesturm des Hasses 1</t>, was sich auf alle Aktionen auswirkt, die mit Interaktionen und Mobilität zu tun haben. Am Ende jeder Drehpause steigt die Stufe um 1.","sz":9.5,"box":[53.9,326.7,285.4,448.7],"p":83,"i":4,"sec":"ein-schneesturm-des-hasses"},{"t":"p","x":"• <b>Das totale Alle-gegen-alle-Chaos</b>: Der Schneesturm ist ein einmaliges Ereignis, das die Stadt zu zerstören droht. Wer mit dem Schnee in Berührung kommt, wird sofort zur bösartigen Wahnsinnigen (<t>hasserfüllt 4</t>). Ohne Therapie wird dieser Hass bei längerer Einwirkung allumfassend (Stufe 5) und dann dauerhaft (Stufe 6). Manche gehen auf die Straße, um ihre Mitmenschen zu töten, ehe sie selbst getötet werden, während andere Schutz suchen, um dann mit ihrem Selbsthass zu kämpfen. Innerhalb von Tagen, vielleicht sogar Stunden, brechen die sozialen Strukturen der Stadt zusammen.","sz":9.5,"box":[53.9,457.3,285.9,604.3],"p":83,"i":5,"sec":"ein-schneesturm-des-hasses"},{"t":"p","x":"Die SC können den Zustand in bestimmten Bereichen mit einer <i>Mega!</i>-<b>Das Blatt wenden</b>-Aktion mit der Option des großflächigen Effekts verringern oder entfernen. Um ihn aus der gesamten Stadt zu entfernen bedarf es einer erzählerischen Lösung, wie z. B. Knight davon zu überzeugen, den Sturm zu beenden, eine kleine Armee gleichgesinnter Risse zu rekrutieren, die zusammenarbeiten und die Spiegelscherben schmelzen, oder eine <b>Jetzt reicht’s!</b>-Aktion mit einem unumkehrbaren oder ultimativen Opfer (SL-Entscheid).","sz":9.5,"box":[53.9,615.8,284.6,737.8],"p":83,"i":6,"sec":"ein-schneesturm-des-hasses"},{"t":"card","x":"<u>ABSPANN</u>","sz":null,"k":"yellow","box":[296.6,56.4,417.6,82.1],"p":83,"i":7,"sec":"ein-schneesturm-des-hasses"},{"t":"p","x":"Im Folgenden findest du einige Fragen, die du dir stellen solltest, und Punkte, die es beim Abschluss dieses Falles noch einmal zu überdenken gilt:","sz":9.5,"box":[309.0,97.7,537.4,132.2],"p":83,"i":8,"sec":"ein-schneesturm-des-hasses"},{"t":"p","x":"• Ist die Bombe explodiert oder hat das Team den von Krystal Knight geplanten Schneesturm des Hasses abgewehrt? Wenn sie explodiert ist, wird die Stadt in den nächsten Wochen, Monaten oder gar Jahren mit diesem traumatischen Ereignis zurechtkommen müssen. Wenn das Team die Krise abgewendet hat, erlangt es dadurch Ruhm bei den Schläfer:innen oder Rissen? Haben die SC entdeckt, dass die Magie des Spiegels überall in der Stadt in Glas eingearbeitet ist, und wenn ja, wie wollen sie sie entschärfen?","sz":9.5,"box":[309.0,143.7,536.2,265.7],"p":83,"i":9,"sec":"ein-schneesturm-des-hasses"},{"t":"p","x":"• Was war das Ende Dr. Krystal Knights, der Gralsritterin? Ist sie tot, im Gefängnis oder wurde sie festgesetzt? Hat sie Heilung gefunden und muss sich nun dem Leid stellen, das sie verursacht hat? Ist sie entkommen oder hat sie den Kampf gar gewonnen und plant nun von ihrem Versteck aus den nächsten Angriff auf die Stadt? Welche Rolle wird sie im Kampf gegen Corbin Payne spielen?","sz":9.5,"box":[309.0,274.4,539.7,371.4],"p":83,"i":10,"sec":"ein-schneesturm-des-hasses"},{"t":"p","x":"• Was haben diese emotionale Episode (und ihr Plot) mit dem Team und den Nebendarsteller:innen gemacht? Haben Beziehungen irreversiblen Schaden genommen? Konnten Teammitglieder ihre Probleme verarbeiten? Nehmen einige von ihnen ihr Riss-Sein mehr als zuvor an oder lehnen es stärker ab?","sz":9.5,"box":[309.0,380.0,538.9,452.0],"p":83,"i":11,"sec":"ein-schneesturm-des-hasses"},{"t":"p","x":"• Was geschah mit den Opfern von Heilung für die Gebrochenen, Felicia Pema Jones und Ruben Stone (sowie Martha Ellis und Maximilian Drake)? Haben sie sich erholt und ihren Platz als Risse gefunden? Konnten sie ihren Geist von den toxischen Gedanken reinigen, die ihnen ihre Therapeut:innen eingeflößt hatten? Haben einige versucht, die Täter:innen zur Rede zu stellen oder gar Rache zu nehmen?","sz":9.5,"box":[309.0,460.7,540.7,557.7],"p":83,"i":12,"sec":"ein-schneesturm-des-hasses"},{"t":"p","x":"• Wie ist Heilung für die Gebrochenen aus der Sache herausgekommen? Führt die Organisation nach wie vor Risse in die Irre, oder hat das Team ihr das Handwerk gelegt? Hat sich Heilung für die Gebrochenen nach dem Verlust der Leiterin aufgelöst, und sind die Therapeut:innen wieder zu Schläfer:innen geworden oder ihrerseits erwacht? Haben sie einen neuen Riss gefunden, der sie wach hält? Wie ist ihre Beziehung zu Rissen nach all dem?","sz":9.5,"box":[309.0,566.4,540.7,675.9],"p":83,"i":13,"sec":"ein-schneesturm-des-hasses"},{"t":"p","x":"• Bleibt die Anstalt bestehen? Ist es Zeit, diese schreckliche Einrichtung zu schließen oder zu modifizieren und in einen Ort der Heilung zu verwandeln? Beschließt das Team, dass es ein neues Gefängnis für geistesgestörte Schurk:innen braucht?","sz":9.5,"box":[309.0,684.5,541.4,744.0],"p":83,"i":14,"sec":"ein-schneesturm-des-hasses"}],"size":[595.276,841.89]}},"figures":[{"id":"eisberg","page":64,"kind":"eisberg","title":"Der Eisberg","file":"img/case03/eisberg.webp","box":[0,0,595,470],"after":null},{"id":"wiege-szene","page":66,"kind":"art","title":"Felicia und das Kind","file":"img/case03/wiege-szene.webp","box":[0,521,595,795],"after":null},{"id":"karte-geraldine","page":72,"kind":"handout","title":"Themenkarte: Geraldine Granger","file":"img/case03/karte-geraldine.webp","box":[51,335,287,670],"after":null},{"id":"karte-thaumaturg","page":72,"kind":"handout","title":"Themenkarte: Der Thaumaturg","file":"img/case03/karte-thaumaturg.webp","box":[306,399,542,760],"after":null},{"id":"anstalt-art","page":74,"kind":"art","title":"Die Städtische Anstalt","file":"img/case03/anstalt-art.webp","box":[0,450,595,795],"after":null},{"id":"anstalt-plan","page":75,"kind":"plan","title":"Grundrisse der Anstalt","file":"img/case03/anstalt-plan.webp","box":[0,0,595,795],"after":null},{"id":"torwaechter","page":78,"kind":"art","title":"Torwächter:innen-Spezialeinheit","file":"img/case03/torwaechter.webp","box":[318,264,536,780],"after":null},{"id":"krankenwagen","page":82,"kind":"art","title":"Krankenwagen mit Schallbombe","file":"img/case03/krankenwagen.webp","box":[0,597,595,795],"after":null}],"eisberg":{"page":64,"fig":"eisberg","nodes":[{"label":"Eine verzweifelte Mutter","layer":0,"x":33.7,"y":11.8,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Frühere Fälle","layer":0,"x":49.2,"y":11.4,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Nebenrollen","layer":0,"x":64.8,"y":11.4,"w":11,"h":9.5,"target":"schicht-0-aufhaenger"},{"label":"Wohnung der Familie Jones","layer":1,"x":30.6,"y":19.6,"w":11,"h":9.5,"target":"wohnung-der-familie-jones"},{"label":"Die Privatklinik von Heilung für die Gebrochenen","layer":1,"x":44.8,"y":19.2,"w":11,"h":9.5,"target":"privatklinik-von-heilung-fuer-die-gebrochenen"},{"label":"Supervision","layer":1,"x":58.1,"y":19.2,"w":11,"h":9.5,"target":"supervision"},{"label":"Der misslungene Golem","layer":1,"x":72.8,"y":19.8,"w":11,"h":9.5,"target":"der-misslungene-golem"},{"label":"Die Anstalt","layer":2,"x":43.3,"y":27.5,"w":11,"h":9.5,"target":"die-anstalt"},{"label":"Die Historische Gesellschaft","layer":2,"x":57.6,"y":27.9,"w":11,"h":9.5,"target":"die-historische-gesellschaft"},{"label":"Die „Spezialabteilung“","layer":3,"x":42.8,"y":35.0,"w":11,"h":9.5,"target":"die-spezialabteilung"},{"label":"Aurora Glas","layer":3,"x":57.6,"y":35.3,"w":11,"h":9.5,"target":"aurora-glas"},{"label":"Ein Schneesturm des Hasses","layer":4,"x":49.2,"y":43.6,"w":11,"h":9.5,"target":"ein-schneesturm-des-hasses"}]}};
